INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MEASURE 4.2', 'MEASURE 4', 'MEASURE 4.2', 'Measurement results regarding AI system trustworthiness in deployment context(s) and target community(ies) are informed by domain expert and AI actor input.', '[]'::JSONB, 54);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 1.1', 'MANAGE 1', 'MANAGE 1.1', 'A determination is made as to whether the AI system achieves its intended purpose and stated objectives and whether its development or deployment should proceed.', '[]'::JSONB, 55);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 1.2', 'MANAGE 1', 'MANAGE 1.2', 'Treatment of documented AI risks is prioritized based on impact, likelihood, or available resources or methods.', '[]'::JSONB, 56);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 1.3', 'MANAGE 1', 'MANAGE 1.3', 'Responses to the AI risks deemed high priority, are developed, planned, and documented.', '[]'::JSONB, 57);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 1.4', 'MANAGE 1', 'MANAGE 1.4', 'Negative residual risks to both downstream acquirers of AI systems and end users are documented.', '[]'::JSONB, 58);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 2.1', 'MANAGE 2', 'MANAGE 2.1', 'Resources required to manage AI risks are taken into account, along with viable non-AI alternative systems.', '[]'::JSONB, 59);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 2.2', 'MANAGE 2', 'MANAGE 2.2', 'Mechanisms are in place and applied to sustain the value of deployed AI systems.', '[]'::JSONB, 60);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 2.3', 'MANAGE 2', 'MANAGE 2.3', 'Procedures are followed to respond to and recover from a previously unknown risk when it is identified.', '[]'::JSONB, 61);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 2.4', 'MANAGE 2', 'MANAGE 2.4', 'Mechanisms are in place and applied to supersede, disengage, or deactivate AI systems that demonstrate performance or outcomes inconsistent with intended use.', '[]'::JSONB, 62);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 3.1', 'MANAGE 3', 'MANAGE 3.1', 'AI risks and benefits from third-party resources are regularly monitored, and risk controls are applied and documented.', '[]'::JSONB, 63);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 3.2', 'MANAGE 3', 'MANAGE 3.2', 'Pre-trained models which are used for development are monitored as part of AI system regular monitoring and maintenance.', '[]'::JSONB, 64);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 4.1', 'MANAGE 4', 'MANAGE 4.1', 'Post-deployment AI system monitoring plans are implemented, including mechanisms for capturing and evaluating input from users and other relevant AI actors.', '[]'::JSONB, 65);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 4.2', 'MANAGE 4', 'MANAGE 4.2', 'Measurable activities for continual improvements are integrated into AI system updates and include regular engagement with interested parties.', '[]'::JSONB, 66);
INSERT INTO sentinel_subcategories (id, category_id, name, description, suggested_actions, sort_order) VALUES ('MANAGE 4.3', 'MANAGE 4', 'MANAGE 4.3', 'Incidents and errors are communicated to relevant AI actors including affected communities.', '[]'::JSONB, 67);
INSERT INTO sentinel_trustworthy_characteristics (id, name, description, is_foundational, is_crosscutting, sort_order) VALUES ('valid_reliable', 'Valid and Reliable', 'Validation is the confirmation that AI system requirements are fulfilled. Reliability means the system can perform as required without failure for a given time period and conditions. An AI system is valid when it meets its stated purpose and intended use.', TRUE, FALSE, 1);
INSERT INTO sentinel_trustworthy_characteristics (id, name, description, is_foundational, is_crosscutting, sort_order) VALUES ('safe', 'Safe', 'AI systems should not endanger human life, health, property, or the environment. Safe operation includes protection from both identified and reasonably foreseeable risks.', FALSE, FALSE, 2);
INSERT INTO sentinel_trustworthy_characteristics (id, name, description, is_foundational, is_crosscutting, sort_order) VALUES ('secure_resilient', 'Secure and Resilient', 'AI systems, as well as the ecosystems in which they are deployed, should be secure and resilient. Resilience refers to the ability to return to normal function after an unexpected adverse event.', FALSE, FALSE, 3);
INSERT INTO sentinel_trustworthy_characteristics (id, name, description, is_foundational, is_crosscutting, sort_order) VALUES ('accountable_transparent', 'Accountable and Transparent', 'Transparency reflects the extent to which information about an AI system is available to individuals interacting with it. Accountability presupposes transparency.', FALSE, TRUE, 4);
INSERT INTO sentinel_trustworthy_characteristics (id, name, description, is_foundational, is_crosscutting, sort_order) VALUES ('explainable_interpretable', 'Explainable and Interpretable', 'Explainability refers to a representation of the mechanisms underlying an algorithm''s operation. Interpretability refers to the meaning of an AI system''s output in the context of its designed functional purposes.', FALSE, FALSE, 5);
INSERT INTO sentinel_trustworthy_characteristics (id, name, description, is_foundational, is_crosscutting, sort_order) VALUES ('privacy_enhanced', 'Privacy-Enhanced', 'Privacy refers generally to the norms and practices that help to safeguard human autonomy, identity, and dignity. Privacy values such as anonymity, confidentiality, and control are supported by privacy-enhancing technologies.', FALSE, FALSE, 6);
INSERT INTO sentinel_trustworthy_characteristics (id, name, description, is_foundational, is_crosscutting, sort_order) VALUES ('fair_bias_managed', 'Fair with Harmful Bias Managed', 'Fairness in AI includes concerns about equality and equity by addressing issues such as harmful bias and discrimination. Standards of fairness can be used to assess AI system impacts.', FALSE, FALSE, 7);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.1-001', 'GOVERN 1.1', 'The organization maintains an inventory of all applicable AI-related laws, regulations, and supervisory guidance (e.g., SR 11-7, OCC 2011-12, EU AI Act, state-level AI statutes) and maps them to AI systems in use.', 'Establish a regulatory tracking process that identifies new and updated AI-related requirements. Assign ownership to legal/compliance for maintaining the inventory. Map each regulation to affected AI systems and business lines. Review quarterly and after any regulatory publication.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Failure to track regulatory requirements may result in non-compliance, supervisory action, enforcement orders, or consent decrees from banking regulators.', 'accountable_transparent', 1);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.1-002', 'GOVERN 1.1', 'AI governance policies explicitly address requirements from prudential regulators, including the OCC, Federal Reserve, FDIC, and CFPB, as well as industry-specific standards such as FFIEC guidance.', 'Draft AI governance policies that reference specific regulatory expectations. Include provisions for model risk management per SR 11-7, fair lending per ECOA/Reg B, and consumer protection per UDAAP. Ensure board-level approval of policies.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Generic AI policies that do not address financial services regulatory specifics create gaps in compliance coverage and increase examination risk.', 'accountable_transparent', 2);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.1-003', 'GOVERN 1.1', 'The organization monitors proposed rulemaking, supervisory statements, and interagency guidance related to AI and updates its compliance program proactively.', 'Subscribe to Federal Register notices, OCC bulletins, Fed supervision letters, and CFPB advisory opinions. Assign a regulatory change management function to assess impact of proposed rules on AI systems. Conduct gap analyses within 60 days of final rule publication.', '{"scaling","full_implementation"}'::TEXT[], 'Reactive compliance posture leads to rushed implementations, control gaps, and potential MRA/MRIA findings during examinations.', 'accountable_transparent', 3);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.2-001', 'GOVERN 1.2', 'The organization maintains a tiered AI risk classification framework that categorizes AI systems by risk level (e.g., critical, high, medium, low) based on impact to consumers, safety, and financial stability.', 'Define risk tiers aligned with SR 11-7 model tiering. Consider factors such as consumer impact, financial materiality, operational criticality, and reputational risk. Assign tier-specific control requirements. Review classifications annually or upon material change.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without risk-based tiering, the organization may over-invest in low-risk AI while under-managing high-risk systems that could cause consumer harm or systemic issues.', 'accountable_transparent', 4);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.2-002', 'GOVERN 1.2', 'AI risk classification explicitly considers fair lending implications, BSA/AML exposure, and consumer protection risks as elevated risk factors for financial services AI systems.', 'Include fair lending, BSA/AML, and UDAAP risk as mandatory evaluation criteria in the AI risk tiering methodology. Systems used in credit decisioning, fraud detection, or customer-facing interactions should receive heightened scrutiny regardless of technical complexity.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems that affect consumer access to financial products carry outsized regulatory and reputational risk that generic tiering frameworks may underweight.', 'fair_bias_managed', 5);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.2-003', 'GOVERN 1.2', 'The risk classification framework is reviewed and approved by the model risk management function and aligned with the organization''s enterprise risk appetite statement.', 'Ensure MRM (Model Risk Management) validates the AI risk tiering methodology. Align AI risk appetite with board-approved enterprise risk appetite. Document how AI risk classifications feed into enterprise risk reporting and capital planning.', '{"scaling","full_implementation"}'::TEXT[], 'Disconnected AI risk classification from enterprise risk management creates blind spots in board reporting and capital adequacy assessments.', 'accountable_transparent', 6);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.3-001', 'GOVERN 1.3', 'The organization defines and documents acceptable AI use boundaries, including explicit prohibitions on AI applications that conflict with fair lending laws, consumer protection requirements, or safety-and-soundness standards.', 'Publish an AI acceptable use policy that specifies permitted and prohibited use cases. Prohibit autonomous credit decisioning without human review for high-risk decisions. Define guardrails for generative AI in customer communications. Review annually with legal and compliance.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Absence of defined AI use boundaries leads to ad hoc deployments that may violate regulatory expectations or cause consumer harm.', 'safe', 7);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.3-002', 'GOVERN 1.3', 'AI use boundaries address the use of generative AI for financial advice, investment recommendations, and insurance underwriting, with specific controls for hallucination risk and unauthorized practice.', 'Establish specific policies for GenAI in customer-facing financial contexts. Require human review of any AI-generated financial advice. Implement output filtering to prevent unauthorized investment or insurance recommendations. Document legal review of GenAI customer interactions.', '{"scaling","full_implementation"}'::TEXT[], 'Uncontrolled generative AI in financial advisory contexts risks regulatory violation under the Investment Advisers Act, state insurance laws, and FINRA rules.', 'valid_reliable', 8);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.3-003', 'GOVERN 1.3', 'Processes exist to evaluate and approve new AI use cases against defined boundaries before development begins, including assessment of regulatory implications by compliance and legal functions.', 'Implement an AI use case intake process requiring compliance, legal, and risk sign-off before development. Use a standardized assessment template covering regulatory requirements, consumer impact, and risk tier. Maintain an approval log auditable by examiners.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Developing AI systems without pre-approval creates compliance risks that are costly to remediate post-deployment and may draw supervisory criticism.', 'accountable_transparent', 9);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.4-001', 'GOVERN 1.4', 'The organization establishes an AI ethics framework that addresses fairness, transparency, accountability, and consumer protection in alignment with regulatory expectations for financial institutions.', 'Develop an AI ethics framework endorsed by senior management. Address bias and fairness in lending and insurance. Include principles for transparency in AI-driven decisions that affect consumers. Align with OCC heightened standards and CFPB expectations on algorithmic fairness.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Financial institutions without an AI ethics framework face reputational risk and regulatory scrutiny, particularly from the CFPB on algorithmic fairness.', 'fair_bias_managed', 10);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.4-002', 'GOVERN 1.4', 'The AI ethics framework is operationalized through defined processes for ethical review of AI systems, including standing ethics review boards or committees with cross-functional representation.', 'Establish an AI ethics review committee with representatives from risk, compliance, legal, business lines, and technology. Define triggers for ethical review (e.g., consumer-facing AI, credit decisions, surveillance). Document review outcomes and remediation actions.', '{"scaling","full_implementation"}'::TEXT[], 'Ethics frameworks without operational processes remain aspirational and fail to prevent harmful AI deployments in practice.', 'fair_bias_managed', 11);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.4-003', 'GOVERN 1.4', 'Ethical considerations specific to financial services are documented, including the ethical implications of AI in credit access, wealth management, fraud detection, and employment decisions within the institution.', 'Document domain-specific ethical considerations for each major AI use case category. Address disparate impact in credit and insurance. Consider surveillance ethics in fraud/AML monitoring. Evaluate employee impact of AI-driven workforce decisions. Review annually.', '{"scaling","full_implementation"}'::TEXT[], 'Generic AI ethics policies miss the unique ethical dimensions of financial services, such as AI''s potential to perpetuate redlining patterns or exclude underbanked populations.', 'fair_bias_managed', 12);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.5-001', 'GOVERN 1.5', 'The organization defines and enforces minimum technical standards for AI system development, testing, deployment, and monitoring, consistent with model risk management expectations under SR 11-7.', 'Publish AI technical standards covering development lifecycle, code review, testing requirements, deployment gates, and monitoring. Align with SR 11-7 expectations for model development, implementation, and use. Include standards for data management, version control, and reproducibility.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Inconsistent technical standards across AI initiatives lead to quality issues, deployment failures, and examination findings on model risk management.', 'valid_reliable', 13);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.5-002', 'GOVERN 1.5', 'Technical standards address the unique risks of third-party and open-source AI models, including foundation models, with requirements for evaluation, customization controls, and ongoing monitoring.', 'Define standards for evaluating third-party AI models before adoption. Require documentation of model provenance, training data characteristics, and known limitations. Establish controls for fine-tuning and prompt engineering of foundation models. Monitor vendor model updates for drift.', '{"scaling","full_implementation"}'::TEXT[], 'Adopting third-party AI models without technical due diligence introduces uncontrolled model risk and potential intellectual property or data privacy issues.', 'secure_resilient', 14);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.5-003', 'GOVERN 1.5', 'Technical standards include requirements for AI system documentation sufficient to support independent model validation, regulatory examination, and audit review.', 'Require comprehensive model documentation including purpose, methodology, data sources, assumptions, limitations, performance metrics, and validation results. Ensure documentation meets SR 11-7 standards for effective challenge. Maintain documentation in a centralized, version-controlled repository.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Insufficient AI documentation impedes independent validation and examination, resulting in MRA findings and potential restrictions on model use.', 'explainable_interpretable', 15);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.6-001', 'GOVERN 1.6', 'The organization maintains an enterprise-wide AI system inventory (model inventory) that is complete, accurate, and includes all AI/ML models regardless of development source, consistent with SR 11-7 model inventory requirements.', 'Implement a centralized AI/model inventory system. Include all models: internally developed, vendor-provided, open-source, and embedded in third-party products. Capture metadata including risk tier, owner, validation status, deployment status, and regulatory scope. Update inventory in real-time or at minimum quarterly.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Incomplete model inventories are a recurring examination finding and prevent effective oversight of AI risk across the enterprise.', 'accountable_transparent', 16);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.6-002', 'GOVERN 1.6', 'The AI inventory captures sufficient metadata to support risk-based oversight, including model purpose, risk tier, data sensitivity classification, consumer impact assessment, and regulatory applicability.', 'Define mandatory inventory fields aligned with SR 11-7 and internal risk framework. Include: model name, owner, business line, risk tier, validation date, performance metrics, data sources, regulatory scope, and consumer impact rating. Enable filtering and reporting by any field combination.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'An inventory without adequate metadata cannot support risk-based prioritization, leaving high-risk AI systems under-monitored.', 'accountable_transparent', 17);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.6-003', 'GOVERN 1.6', 'Processes ensure that AI systems embedded in vendor products, fintech partnerships, and third-party platforms are identified and included in the AI inventory with appropriate risk assessment.', 'Integrate AI discovery into vendor management and procurement processes. Require vendors to disclose AI/ML components in their products via contractual provisions. Assess embedded AI against the same risk framework as internally developed models. Flag shadow AI use through technology governance controls.', '{"scaling","full_implementation"}'::TEXT[], 'Vendor-embedded AI that escapes inventory creates unmonitored model risk and may violate regulatory expectations for comprehensive model governance.', 'accountable_transparent', 18);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.7-001', 'GOVERN 1.7', 'The organization establishes AI-specific incident response and escalation procedures integrated with existing operational risk and business continuity frameworks.', 'Develop AI incident response playbooks covering model failures, data breaches, bias events, and adversarial attacks. Define severity levels with corresponding response times and escalation paths. Integrate with enterprise incident management and business continuity planning. Include regulatory notification requirements.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI system failures without predefined response procedures lead to prolonged outages, consumer harm, and delayed regulatory notifications.', 'safe', 19);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.7-002', 'GOVERN 1.7', 'AI incident response procedures include defined triggers for regulatory notification, including materiality thresholds aligned with OCC, FDIC, and state regulatory reporting requirements.', 'Map AI incident types to regulatory notification requirements. Define materiality thresholds for reporting to the OCC (e.g., significant operational disruption), state regulators (data breach notification), and the CFPB (consumer harm). Establish maximum time-to-notify aligned with regulatory expectations. Conduct tabletop exercises annually.', '{"scaling","full_implementation"}'::TEXT[], 'Failure to timely notify regulators of material AI incidents can result in enforcement action and loss of supervisory trust.', 'accountable_transparent', 20);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.7-003', 'GOVERN 1.7', 'Post-incident review processes are established for AI system failures, including root cause analysis, lessons learned, and control remediation tracked to completion.', 'Require post-incident reviews for all AI incidents above a defined severity threshold. Conduct root cause analysis within 30 days. Document lessons learned and share across AI teams. Track remediation actions to closure with second-line oversight. Report trends to the risk committee quarterly.', '{"scaling","full_implementation"}'::TEXT[], 'Without structured post-incident review, the organization fails to learn from AI failures and repeats preventable incidents.', 'valid_reliable', 21);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.1-001', 'GOVERN 2.1', 'Roles and responsibilities for AI risk management are clearly defined across the three lines of defense, with the first line owning AI systems, the second line providing independent oversight, and the third line providing assurance.', 'Document AI-specific responsibilities for each line of defense. First line: model development, implementation, ongoing monitoring. Second line (MRM, compliance): independent validation, policy setting, risk assessment. Third line (internal audit): assurance over AI governance effectiveness. Define RACI matrices for key AI processes.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Ambiguous AI responsibilities across defense lines lead to control gaps, duplicated effort, or inadequate independent oversight — a common examination criticism.', 'accountable_transparent', 22);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.1-002', 'GOVERN 2.1', 'A senior executive (e.g., Chief AI Officer, Chief Data Officer, or Chief Risk Officer) is designated with enterprise-wide accountability for AI risk management and governance.', 'Assign a named senior executive with authority and accountability for AI governance. Define reporting lines to the board risk committee. Ensure the role has sufficient independence, resources, and organizational stature. Document the designation in governance policies and communicate to regulators.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without clear senior executive ownership, AI governance lacks authority and accountability, resulting in fragmented oversight across business lines.', 'accountable_transparent', 23);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.1-003', 'GOVERN 2.1', 'AI system owners are formally designated for each AI system in the inventory, with documented accountability for risk management, performance, and compliance throughout the model lifecycle.', 'Require formal designation of a model/system owner for each AI system at registration. Define owner responsibilities including ongoing monitoring, issue remediation, validation coordination, and regulatory response. Ensure owners have sufficient technical understanding to fulfill accountability. Review ownership assignments annually.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Unowned AI systems drift without accountability, accumulating risk through unmonitored performance degradation and unresolved issues.', 'accountable_transparent', 24);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.2-001', 'GOVERN 2.2', 'The organization conducts AI-specific skills assessments and maintains training programs to ensure staff across all three lines of defense have competency appropriate to their AI responsibilities.', 'Assess AI literacy needs by role (developers, validators, compliance officers, auditors, executives). Develop tiered training programs from AI awareness to advanced technical skills. Track completion and competency assessment results. Require recertification annually. Budget for external training and conferences.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Insufficient AI competency across defense lines leads to ineffective development, validation, and oversight — a known driver of model risk events.', 'accountable_transparent', 25);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.2-002', 'GOVERN 2.2', 'Model risk management and internal audit functions maintain sufficient expertise in AI/ML techniques to provide effective challenge and assurance over AI systems.', 'Hire or develop AI/ML specialists within MRM and audit functions. Ensure validators can independently assess model methodology, data quality, and performance. Provide audit staff with training on AI-specific risks and controls. Supplement with qualified third-party specialists where internal expertise is insufficient.', '{"scaling","full_implementation"}'::TEXT[], 'Second and third line functions lacking AI expertise cannot provide effective challenge, undermining the three lines of defense model for AI.', 'accountable_transparent', 26);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.2-003', 'GOVERN 2.2', 'Board members and senior executives receive regular AI literacy training sufficient to exercise informed oversight of AI strategy, risks, and governance.', 'Provide at minimum annual AI education sessions for the board and executive committee. Cover AI capabilities, limitations, risks, regulatory landscape, and the organization''s AI strategy. Use case studies relevant to financial services. Assess board comprehension and adjust content accordingly.', '{"scaling","full_implementation"}'::TEXT[], 'Boards lacking AI understanding cannot exercise meaningful oversight, resulting in rubber-stamp approvals and inadequate strategic direction.', 'accountable_transparent', 27);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.3-001', 'GOVERN 2.3', 'The board of directors or a designated board committee receives regular reporting on AI risk exposure, governance effectiveness, and material AI incidents, with sufficient detail to exercise oversight.', 'Establish quarterly AI risk reporting to the board risk committee. Include: AI inventory summary, risk tier distribution, validation status, open issues, performance metrics, incidents, and emerging risks. Provide trend analysis and comparison to risk appetite. Ensure reports are actionable and not purely informational.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Inadequate board reporting on AI risk impairs governance and may result in examination findings on board oversight effectiveness.', 'accountable_transparent', 28);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.3-002', 'GOVERN 2.3', 'Senior management AI governance committees meet regularly with defined charters, membership requirements, and decision-making authority over AI strategy, risk acceptance, and resource allocation.', 'Establish an AI governance committee with a formal charter. Define membership to include CRO, CDO/CAIO, business line heads, compliance, legal, and technology leadership. Meet at minimum monthly. Document decisions, action items, and escalations. Report to the board committee quarterly.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI governance without a structured committee process leads to inconsistent decision-making and inadequate senior management engagement.', 'accountable_transparent', 29);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.3-003', 'GOVERN 2.3', 'Internal audit includes AI governance and model risk management within its audit universe, with risk-based audit planning that covers the full AI lifecycle.', 'Include AI governance, MRM, and individual high-risk AI systems in the audit universe. Develop a risk-based audit plan that covers AI strategy, development practices, validation, monitoring, and third-party AI. Execute AI audits using staff with appropriate AI expertise. Report findings to the audit committee.', '{"scaling","full_implementation"}'::TEXT[], 'Excluding AI from the audit universe leaves governance effectiveness unassured and may result in regulatory criticism of audit coverage.', 'accountable_transparent', 30);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-3.1-001', 'GOVERN 3.1', 'The organization integrates AI risk into its enterprise risk management framework, with AI-specific risk categories, appetite statements, and reporting aligned with existing operational, compliance, and strategic risk processes.', 'Extend the ERM taxonomy to include AI-specific risk categories (model risk, algorithmic bias, AI operational risk). Define AI risk appetite metrics and thresholds approved by the board. Integrate AI risk reporting into enterprise risk dashboards. Align AI risk assessment methodology with existing ERM processes.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Siloed AI risk management disconnected from ERM creates blind spots in enterprise risk reporting and may understate aggregate risk exposure.', 'accountable_transparent', 31);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-3.1-002', 'GOVERN 3.1', 'AI risk appetite and tolerance levels are defined, quantified where possible, and approved by the board, with clear escalation procedures when tolerances are breached.', 'Define quantitative AI risk appetite metrics (e.g., maximum model risk losses, bias thresholds, system availability). Set tolerance levels with escalation triggers. Monitor metrics continuously against thresholds. Escalate breaches per defined procedures. Review appetite annually or after material events.', '{"scaling","full_implementation"}'::TEXT[], 'Undefined AI risk appetite means the organization cannot objectively determine whether AI risk is within acceptable bounds.', 'accountable_transparent', 32);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-3.1-003', 'GOVERN 3.1', 'AI risk assessments consider interconnections between AI systems and critical financial infrastructure, including payment systems, clearing houses, and SIFMUs.', 'Map AI system dependencies on critical financial infrastructure. Assess concentration risk where multiple AI systems depend on shared infrastructure or data sources. Evaluate systemic risk implications of AI failures in market-critical functions. Include interconnection analysis in risk assessments for high-tier AI systems.', '{"full_implementation"}'::TEXT[], 'Ignoring AI interconnections with critical infrastructure could contribute to systemic risk events that affect financial stability.', 'safe', 33);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-3.2-001', 'GOVERN 3.2', 'The organization establishes AI-specific policies and procedures that are reviewed at least annually, approved by appropriate governance bodies, and communicated to all relevant personnel.', 'Maintain a policy framework covering AI governance, development standards, validation, monitoring, third-party AI, and acceptable use. Require annual review and approval by the AI governance committee. Version-control all policies. Distribute to relevant personnel with acknowledgment tracking. Align with enterprise policy management standards.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Outdated or poorly communicated AI policies lead to inconsistent practices and examination findings on governance effectiveness.', 'accountable_transparent', 34);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-3.2-002', 'GOVERN 3.2', 'AI policies address the full model lifecycle from ideation through decommissioning, with specific requirements for each phase aligned with SR 11-7 expectations.', 'Define policy requirements for each lifecycle phase: use case approval, development standards, validation, implementation, ongoing monitoring, change management, and decommissioning. Specify gate criteria for progression between phases. Require documentation at each stage. Align with SR 11-7 lifecycle management expectations.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Lifecycle gaps in AI policy coverage allow AI systems to bypass controls at critical transition points, increasing risk.', 'accountable_transparent', 35);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-3.2-003', 'GOVERN 3.2', 'Exception management processes exist for AI policy deviations, with risk-based approval authority, time-bound remediation plans, and second-line oversight.', 'Define an exception process for AI policy deviations. Require risk assessment of each exception. Assign approval authority based on risk level (e.g., CRO for high-risk exceptions). Set maximum exception duration with mandatory remediation plans. Track exceptions centrally. Report to governance committee quarterly.', '{"scaling","full_implementation"}'::TEXT[], 'Unmanaged policy exceptions accumulate risk and undermine the governance framework, potentially creating systemic control weaknesses.', 'accountable_transparent', 36);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.1-001', 'GOVERN 4.1', 'The organization allocates sufficient budget, staff, and technology resources to support AI risk management activities proportionate to the scale and complexity of its AI program.', 'Conduct annual resource needs assessment for AI risk management. Budget for MRM staffing, validation tools, monitoring infrastructure, and training. Benchmark resource levels against peer institutions and regulatory expectations. Ensure resource allocation is approved by senior management and reported to the board.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Under-resourced AI risk management cannot keep pace with AI deployment, creating a growing gap between AI use and oversight capacity.', 'accountable_transparent', 37);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.1-002', 'GOVERN 4.1', 'Resource allocation for AI validation and monitoring scales with the AI inventory, ensuring that validation backlogs do not create unacceptable risk exposure from unvalidated models in production.', 'Track validation backlog as a key risk metric. Define maximum acceptable time-to-validation by risk tier. Allocate MRM resources to maintain backlog within tolerance. Use risk-based prioritization to sequence validation work. Escalate capacity constraints to governance committee when backlogs exceed thresholds.', '{"scaling","full_implementation"}'::TEXT[], 'Validation backlogs leave AI systems operating without independent challenge, a primary driver of model risk events in financial services.', 'valid_reliable', 38);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.1-003', 'GOVERN 4.1', 'The organization invests in AI risk management tooling, including model monitoring platforms, bias detection tools, and documentation repositories, to enable scalable AI governance.', 'Evaluate and implement AI governance technology including model monitoring, experiment tracking, bias analysis, and documentation management. Prioritize tools that support regulatory reporting requirements. Ensure tooling is accessible to all three lines of defense. Conduct build-vs-buy analysis for key capabilities.', '{"scaling","full_implementation"}'::TEXT[], 'Manual AI governance processes do not scale, leading to monitoring gaps and inconsistent control execution as the AI program grows.', 'accountable_transparent', 39);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.2-001', 'GOVERN 4.2', 'The organization maintains competency requirements for AI roles, including model developers, data engineers, validators, and AI risk managers, with hiring practices that attract qualified talent.', 'Define competency frameworks for AI-related roles. Require minimum qualifications for model developers (statistics, ML, programming) and validators (independent technical capability). Develop competitive compensation packages. Establish partnerships with universities and AI research institutions for talent pipeline.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Inability to attract and retain qualified AI talent leads to quality issues in development, validation gaps, and reliance on unqualified staff.', 'accountable_transparent', 40);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.2-002', 'GOVERN 4.2', 'Staff involved in AI development, deployment, and oversight receive role-specific training on financial services regulations, ethical AI practices, and the organization''s AI governance framework.', 'Develop mandatory training curricula differentiated by role. Include regulatory context (SR 11-7, fair lending, BSA/AML) for all AI staff. Provide ethics training with financial services scenarios. Require governance framework training for new hires. Track completion and assess effectiveness annually.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Technical AI staff without regulatory and governance training may develop systems that are technically sound but non-compliant or ethically problematic.', 'accountable_transparent', 41);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.2-003', 'GOVERN 4.2', 'Succession planning and knowledge management processes ensure continuity of AI expertise, preventing single points of failure in critical AI system ownership and oversight.', 'Identify key-person dependencies for critical AI systems. Develop succession plans for AI leadership and system owners. Implement knowledge management practices including comprehensive documentation, code comments, and cross-training. Ensure at least two qualified individuals can support each critical AI system.', '{"scaling","full_implementation"}'::TEXT[], 'Key-person dependency in AI creates operational risk when staff depart, potentially leaving critical systems without qualified oversight.', 'secure_resilient', 42);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.3-001', 'GOVERN 4.3', 'AI governance processes are integrated with existing enterprise change management, SDLC, and IT governance frameworks to avoid duplication and ensure consistent control execution.', 'Map AI governance gates to existing SDLC phases. Integrate AI risk assessment into enterprise change management. Align AI documentation requirements with IT governance standards. Use existing ticketing and workflow systems for AI governance activities where possible. Avoid creating parallel processes.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Siloed AI governance creates confusion, duplication, and process fatigue that undermines compliance and increases operational burden.', 'accountable_transparent', 43);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.3-002', 'GOVERN 4.3', 'The organization periodically assesses the effectiveness of its AI governance framework through self-assessments, maturity evaluations, and benchmarking against regulatory expectations and peer practices.', 'Conduct annual AI governance self-assessment against the FS AI RMF. Benchmark against regulatory expectations and peer practices. Identify maturity gaps and develop improvement roadmaps. Report assessment results to the board. Consider independent third-party assessments for objectivity.', '{"scaling","full_implementation"}'::TEXT[], 'Without periodic effectiveness assessment, AI governance may not evolve with the pace of AI adoption and regulatory expectations.', 'accountable_transparent', 44);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.3-003', 'GOVERN 4.3', 'Lessons learned from regulatory examinations, audit findings, and industry events are systematically incorporated into the AI governance framework.', 'Establish a process to capture and analyze regulatory feedback, audit findings, and industry AI incidents. Assess applicability to the organization''s AI program. Prioritize and implement governance framework updates. Track remediation of examination findings with defined timelines. Share learnings across the enterprise.', '{"scaling","full_implementation"}'::TEXT[], 'Failing to incorporate external learnings leads to repeated issues and demonstrates weak continuous improvement to regulators.', 'accountable_transparent', 45);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-5.1-001', 'GOVERN 5.1', 'The organization engages relevant stakeholders — including consumers, community groups, employees, and regulators — in the design and oversight of AI systems that significantly affect them.', 'Identify stakeholder groups affected by each high-risk AI system. Establish feedback mechanisms for consumers (complaint channels, advisory panels). Engage community groups on AI used in lending, particularly in CRA assessment areas. Solicit employee input on AI affecting workplace decisions. Maintain dialogue with examiners on AI plans.', '{"scaling","full_implementation"}'::TEXT[], 'Developing AI without stakeholder engagement risks building systems that fail to meet user needs, exacerbate inequities, or surprise regulators.', 'fair_bias_managed', 46);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-5.1-002', 'GOVERN 5.1', 'Consumer feedback and complaint data related to AI-driven decisions are systematically collected, analyzed, and used to improve AI system fairness and performance.', 'Tag consumer complaints related to AI-driven decisions in the complaint management system. Analyze complaint patterns for bias signals and performance issues. Feed complaint insights into model monitoring and retraining processes. Report AI-related complaint trends to governance committee. Comply with CFPB complaint data expectations.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Ignoring consumer feedback on AI-driven decisions perpetuates harmful outcomes and increases CFPB enforcement risk.', 'fair_bias_managed', 47);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-5.1-003', 'GOVERN 5.1', 'The organization proactively communicates with prudential regulators about material AI initiatives, seeking supervisory feedback before deployment of high-risk AI systems.', 'Include AI initiatives in regular supervisory discussions. Provide advance notice of material AI deployments (e.g., credit decisioning, BSA/AML). Seek informal feedback on novel AI use cases. Prepare AI briefing materials for examination teams. Maintain a constructive relationship with examiners on AI topics.', '{"scaling","full_implementation"}'::TEXT[], 'Surprising regulators with material AI deployments damages supervisory relationships and increases the likelihood of restrictive MRAs.', 'accountable_transparent', 48);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-5.2-001', 'GOVERN 5.2', 'The organization establishes mechanisms for individuals to contest or appeal AI-driven decisions that materially affect them, including credit decisions, account actions, and employment determinations.', 'Implement appeal processes for AI-driven decisions per regulatory requirements (ECOA adverse action, FCRA dispute rights). Ensure human review of contested AI decisions. Track appeal outcomes and identify patterns suggesting systemic issues. Provide clear instructions to affected individuals on how to exercise appeal rights.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Absence of appeal mechanisms for AI decisions violates consumer protection laws and denies individuals due process rights.', 'fair_bias_managed', 49);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-5.2-002', 'GOVERN 5.2', 'Adverse action notices for AI-driven credit decisions comply with ECOA and FCRA requirements, providing specific and accurate reasons for denial that reflect the actual factors in the AI model''s decision.', 'Ensure AI-driven adverse action reasons are derived from the model''s actual decision factors, not generic templates. Validate that reason codes accurately reflect model behavior through regular testing. Comply with CFPB guidance on AI-specific adverse action requirements. Train compliance staff on AI-specific adverse action challenges.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Inaccurate adverse action notices from AI credit models violate ECOA/FCRA and are a leading source of fair lending enforcement actions.', 'explainable_interpretable', 50);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-5.2-003', 'GOVERN 5.2', 'The organization monitors the resolution of contested AI decisions to identify systemic issues and feeds results back into model improvement and governance processes.', 'Track and analyze outcomes of AI decision appeals. Identify patterns such as disproportionate overturns for specific demographic groups. Use appeal data as an input to model fairness monitoring. Escalate systemic findings to model owners and governance committee. Incorporate insights into model retraining where appropriate.', '{"scaling","full_implementation"}'::TEXT[], 'Unanalyzed appeal data represents wasted intelligence on potential model fairness and accuracy issues.', 'fair_bias_managed', 51);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-6.1-001', 'GOVERN 6.1', 'The organization maintains a current understanding of AI-related risks to financial stability, operational resilience, and systemic interconnectedness, informed by industry intelligence and supervisory communications.', 'Monitor emerging AI risks through industry groups (e.g., FS-ISAC, CRI, BIS publications), supervisory speeches, and examination feedback. Assess AI concentration risks in critical financial functions. Evaluate potential for correlated AI failures across institutions. Report emerging risk intelligence to the risk committee.', '{"scaling","full_implementation"}'::TEXT[], 'Failure to monitor emerging AI risks leaves the organization unprepared for novel threats and regulatory shifts.', 'secure_resilient', 52);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-6.1-002', 'GOVERN 6.1', 'AI risk assessments consider macro-level financial stability implications, including the potential for AI-driven herding behavior, flash events, and algorithmic amplification of market stress.', 'Include financial stability considerations in AI risk assessments for trading, market making, and portfolio management AI. Evaluate potential for correlated AI behavior across market participants. Implement circuit breakers and human override mechanisms for AI in market-sensitive functions. Coordinate with prudential supervisors on systemic risk concerns.', '{"full_implementation"}'::TEXT[], 'AI systems in market-sensitive functions can amplify systemic risk through correlated behavior and speed-of-light decision making.', 'safe', 53);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-6.1-003', 'GOVERN 6.1', 'The organization participates in industry forums and information-sharing initiatives related to AI risk management in financial services.', 'Actively participate in CRI FS AI RMF working groups, FS-ISAC AI threat intelligence sharing, and relevant regulatory roundtables. Contribute to and benefit from peer benchmarking on AI governance maturity. Share non-proprietary lessons learned from AI incidents. Engage with standards bodies on AI governance frameworks.', '{"scaling","full_implementation"}'::TEXT[], 'Isolation from industry AI risk intelligence leaves the organization unable to benchmark practices or anticipate emerging regulatory expectations.', 'accountable_transparent', 54);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-6.2-001', 'GOVERN 6.2', 'The organization assesses and manages AI-related risks arising from third-party AI providers, including concentration risk from dependence on a small number of foundation model providers.', 'Inventory all third-party AI dependencies. Assess concentration risk from reliance on major cloud AI and foundation model providers. Develop contingency plans for provider disruption. Include AI-specific provisions in vendor contracts. Monitor provider financial health, security posture, and model change practices.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Concentration in a few AI providers creates systemic dependency that could simultaneously disrupt multiple financial institutions.', 'secure_resilient', 55);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-6.2-002', 'GOVERN 6.2', 'Third-party AI vendor risk assessments include evaluation of the vendor''s own AI governance practices, model development standards, and ability to support the institution''s regulatory obligations.', 'Develop AI-specific vendor due diligence questionnaires. Evaluate vendor AI governance maturity, development practices, testing, and monitoring capabilities. Assess vendor ability to provide model documentation, performance data, and validation support. Include right-to-audit clauses for AI components. Review vendor AI practices at least annually.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Vendors with weak AI governance practices transfer unmanaged model risk to the financial institution, which remains accountable to regulators.', 'accountable_transparent', 56);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-6.2-003', 'GOVERN 6.2', 'Contracts with AI vendors include provisions for model transparency, performance reporting, incident notification, data handling, and regulatory examination access.', 'Negotiate contractual provisions requiring: model documentation disclosure, regular performance reports, prompt incident notification, data handling per institutional standards, and examination access per OCC/Fed expectations. Include provisions for model change notification and approval. Address data ownership and return upon contract termination.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Inadequate contractual provisions limit the institution''s ability to validate, monitor, and demonstrate governance over vendor AI models.', 'accountable_transparent', 57);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.1-001', 'MAP 1.1', 'For each proposed AI use case, the organization documents the intended purpose, scope, target population, expected benefits, and potential risks in a structured use case assessment.', 'Create a standardized AI use case assessment template. Require completion before development begins. Include: business problem, proposed AI approach, target population (with demographic analysis), expected benefits (quantified), potential risks, regulatory implications, and alignment with AI strategy. Review and approve through governance process.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Deploying AI without clear purpose documentation leads to scope creep, unintended uses, and inability to demonstrate AI system intent to regulators.', 'accountable_transparent', 58);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.1-002', 'MAP 1.1', 'Use case assessments for consumer-facing AI include analysis of potential disparate impact on protected classes and underserved populations, including communities identified in CRA assessments.', 'Require pre-deployment disparate impact analysis for AI affecting consumers. Evaluate potential effects across race, gender, age, national origin, and other protected characteristics. Consider impact on underserved populations and CRA assessment areas. Document analysis methodology and findings. Obtain fair lending compliance sign-off before proceeding.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI deployed without disparate impact analysis may perpetuate or amplify discrimination, resulting in fair lending violations and enforcement actions.', 'fair_bias_managed', 59);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.1-003', 'MAP 1.1', 'The organization evaluates whether AI is the appropriate solution for each proposed use case, considering alternatives such as traditional statistical models, rules-based systems, or human processes.', 'Require justification for AI over simpler alternatives. Evaluate whether traditional approaches achieve acceptable performance. Document the incremental benefit of AI versus the additional complexity and risk. Consider explainability requirements — high-explainability needs may favor simpler models. Include cost-benefit analysis in the assessment.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Deploying AI where simpler methods suffice unnecessarily increases model risk, complexity, and governance burden without commensurate benefit.', 'explainable_interpretable', 60);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.2-001', 'MAP 1.2', 'The organization identifies and documents all stakeholders affected by each AI system, including internal users, consumers, regulators, and third parties, and assesses the nature and magnitude of impact on each group.', 'Map stakeholders for each AI system using a structured stakeholder analysis. Categorize by type: direct users, decision subjects, oversight functions, regulators, and ecosystem participants. Assess magnitude of impact (financial, access, privacy, employment). Prioritize high-impact stakeholder groups for engagement and risk mitigation.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Incomplete stakeholder identification leads to overlooked impacts, unaddressed risks, and surprised regulators or consumers.', 'fair_bias_managed', 61);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.2-002', 'MAP 1.2', 'Stakeholder analysis includes specific assessment of consumer impact for AI used in credit, deposit, payment, insurance, and investment products, with particular attention to financially vulnerable populations.', 'Conduct consumer impact assessments for AI in financial products. Analyze effects on credit access, pricing, account management, and service quality. Evaluate impact on LMI borrowers, elderly consumers, LEP individuals, and other vulnerable populations. Align with CFPB guidance on algorithmic harm. Document consumer-specific risk mitigations.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI in financial products that harms vulnerable consumers creates acute regulatory, legal, and reputational risk for the institution.', 'fair_bias_managed', 62);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.2-003', 'MAP 1.2', 'Stakeholder engagement findings are documented and integrated into AI system design decisions, with traceability from stakeholder input to system requirements.', 'Maintain records of stakeholder engagement activities and findings. Create traceability matrices linking stakeholder feedback to design decisions. Document where stakeholder input changed system design versus where it was noted but not incorporated (with justification). Review traceability during validation and audits.', '{"scaling","full_implementation"}'::TEXT[], 'Stakeholder engagement without integration into design is performative and does not reduce actual risk to affected populations.', 'accountable_transparent', 63);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.3-001', 'MAP 1.3', 'The organization defines measurable performance requirements for each AI system, including accuracy, precision, recall, latency, and business-specific metrics, prior to development.', 'Establish quantitative performance requirements during use case approval. Include statistical metrics (accuracy, AUC, precision, recall) and business metrics (dollar impact, processing time, customer satisfaction). Define minimum acceptable thresholds and target performance levels. Document requirements in model development documentation per SR 11-7.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems developed without predefined performance requirements cannot be objectively evaluated, leading to subjective go/no-go decisions.', 'valid_reliable', 64);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.3-002', 'MAP 1.3', 'Performance requirements include fairness metrics with quantitative thresholds, defined for relevant protected class attributes and aligned with fair lending and anti-discrimination requirements.', 'Define fairness metrics appropriate to the use case (e.g., demographic parity, equalized odds, predictive parity). Set quantitative thresholds for acceptable disparity ratios. Require fairness testing across race, gender, age, and other protected characteristics. Align with CFPB and DOJ expectations for fair lending analytics. Document methodology and thresholds.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems without quantitative fairness requirements may pass accuracy tests while producing discriminatory outcomes that trigger enforcement action.', 'fair_bias_managed', 65);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.3-003', 'MAP 1.3', 'Performance requirements include robustness criteria, specifying acceptable performance degradation under stressed conditions, distribution shift, and adversarial scenarios relevant to financial services.', 'Define robustness requirements including performance under economic stress scenarios (recession, rate shock), data quality degradation, and adversarial manipulation. Specify maximum acceptable performance degradation percentages. Align stress scenarios with enterprise stress testing frameworks (CCAR/DFAST where applicable). Test robustness during validation.', '{"scaling","full_implementation"}'::TEXT[], 'AI systems that perform well in normal conditions but fail under stress create procyclical risk that amplifies financial downturns.', 'valid_reliable', 66);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.4-001', 'MAP 1.4', 'The organization identifies and documents risks specific to each AI system, including data risks, model risks, operational risks, and compliance risks, using a structured risk identification methodology.', 'Conduct system-specific risk identification workshops with cross-functional participation (business, technology, risk, compliance). Use structured methodologies such as risk taxonomies, failure mode analysis, or threat modeling. Document identified risks with likelihood, impact, and proposed mitigations. Maintain a risk register for each AI system.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Generic risk assessments miss system-specific risks, leaving unique threat vectors unmitigated.', 'accountable_transparent', 67);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.4-002', 'MAP 1.4', 'AI risk identification explicitly addresses risks unique to AI/ML systems, including concept drift, data poisoning, adversarial attacks, model extraction, and emergent behaviors in complex models.', 'Include AI-specific risk categories in the risk identification process. Assess: concept and data drift, training data poisoning, adversarial manipulation, model theft/extraction, unexpected emergent behaviors (especially in deep learning and foundation models), and hallucination risk (for generative AI). Map each risk to monitoring and control strategies.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Traditional risk identification approaches miss novel AI-specific threats, leaving organizations vulnerable to risks unique to machine learning systems.', 'secure_resilient', 68);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.4-003', 'MAP 1.4', 'Risk identification for AI in financial services includes assessment of risks to financial inclusion, equitable access, and potential for digital redlining or algorithmic exclusion.', 'Evaluate AI systems for potential to create or reinforce barriers to financial access. Assess whether AI-driven eligibility, pricing, or servicing decisions could produce digital redlining effects. Analyze geographic and demographic patterns in AI outcomes. Engage CRA and fair lending officers in risk identification for relevant AI systems.', '{"scaling","full_implementation"}'::TEXT[], 'AI-driven financial exclusion constitutes a modern form of redlining, with severe fair lending, CRA, and reputational consequences.', 'fair_bias_managed', 69);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.5-001', 'MAP 1.5', 'The organization assesses and documents the potential financial, operational, reputational, and consumer impact of AI system failures or adverse outcomes, using quantitative analysis where feasible.', 'Conduct impact assessments for AI system failure scenarios. Quantify potential financial losses (direct and indirect). Assess operational disruption to business lines and customers. Evaluate reputational impact and potential media scrutiny. Estimate consumer harm in terms of affected population size and severity. Use scenario analysis aligned with enterprise stress testing.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Underestimating AI failure impact leads to insufficient controls and inadequate contingency planning for high-consequence events.', 'safe', 70);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.5-002', 'MAP 1.5', 'Impact assessments for AI systems in critical banking functions (payments, clearing, settlement) consider cascading effects on counterparties, market participants, and financial system stability.', 'For AI in systemically important functions, extend impact analysis beyond the institution. Map downstream dependencies and counterparty exposures. Assess potential for cascading failures through payment networks, clearing houses, and correspondent banking relationships. Coordinate with treasury, operations, and market risk functions. Consider SIFMU interconnections.', '{"full_implementation"}'::TEXT[], 'AI failures in critical banking infrastructure can propagate through the financial system, creating systemic risk beyond the originating institution.', 'safe', 71);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.5-003', 'MAP 1.5', 'Impact assessment results are used to determine control intensity, monitoring frequency, and business continuity requirements proportionate to the assessed risk.', 'Link impact assessment results to control requirements. Higher-impact AI systems receive more intensive validation, more frequent monitoring, and more robust fallback procedures. Document the rationale connecting impact assessment to control design. Review impact assessments annually or after material changes to the AI system or its operating environment.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Impact assessments that do not drive proportionate controls provide false assurance without reducing actual risk.', 'accountable_transparent', 72);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.6-001', 'MAP 1.6', 'The organization evaluates and documents the benefits, costs, and risks of AI systems compared to non-AI alternatives and the status quo, supporting informed go/no-go decisions.', 'Require business case documentation that compares AI to alternatives. Quantify incremental benefit of AI (accuracy improvement, cost reduction, speed gain). Assess incremental risk and governance cost. Document the decision rationale. Require sign-off from business and risk leadership. Reassess periodically as AI performance data accumulates.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Deploying AI without rigorous cost-benefit analysis may result in investments that increase risk without proportionate business value.', 'accountable_transparent', 73);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.6-002', 'MAP 1.6', 'Cost-benefit analysis includes the total cost of AI governance, including validation, monitoring, regulatory compliance, and potential remediation costs, not solely development and operational costs.', 'Include full lifecycle governance costs in AI business cases. Account for: validation resources, ongoing monitoring, regulatory examination support, documentation maintenance, retraining costs, and potential remediation/incident response costs. Use historical data from existing AI systems to improve cost estimates. Update estimates as governance requirements evolve.', '{"scaling","full_implementation"}'::TEXT[], 'Underestimating AI governance costs leads to under-resourced oversight and may make unprofitable AI systems appear viable.', 'accountable_transparent', 74);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.6-003', 'MAP 1.6', 'The organization establishes criteria for discontinuing AI systems that no longer provide sufficient benefit relative to their risk and governance cost.', 'Define trigger criteria for AI system decommissioning review (e.g., declining performance, increasing maintenance cost, regulatory changes, superseding technology). Require periodic value realization reviews for all AI systems. Establish a decommissioning process including data retention, model archival, and transition planning. Ensure decommissioned models are removed from the active inventory.', '{"scaling","full_implementation"}'::TEXT[], 'Legacy AI systems that persist without value realization consume governance resources and may accumulate unmonitored risk.', 'accountable_transparent', 75);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.1-001', 'MAP 2.1', 'The organization defines and validates the target operating environment for each AI system, including data inputs, integration points, user populations, and decision contexts in which the model will operate.', 'Document the intended operating environment comprehensively: data sources and their characteristics, upstream and downstream system integrations, user populations and their technical capabilities, decision contexts and time constraints. Validate that the operating environment matches development assumptions. Monitor for environmental changes post-deployment.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems deployed in environments that differ from development assumptions may produce unexpected and unreliable results.', 'valid_reliable', 76);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.1-002', 'MAP 2.1', 'The organization assesses how AI system outputs will be used in human decision-making processes, including the degree of human reliance, automation level, and override capabilities.', 'Document the human-AI interaction model for each system. Specify whether AI output is advisory, augmenting, or autonomous. Define human override capabilities and when they should be exercised. Assess the risk of automation bias — humans over-relying on AI recommendations. Design user interfaces to support appropriate skepticism. Test human-AI decision quality jointly.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Poorly designed human-AI interaction leads to automation bias or disuse, negating the intended benefits of AI augmentation.', 'explainable_interpretable', 77);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.1-003', 'MAP 2.1', 'For AI used in real-time transaction processing (payments, trading, fraud detection), the operating environment assessment includes latency requirements, throughput capacity, and failover procedures.', 'Define performance SLAs for real-time AI systems including maximum latency, minimum throughput, and availability targets. Test under peak load conditions. Implement graceful degradation and fallback to rules-based processing. Define automated and manual failover procedures. Align with enterprise business continuity and disaster recovery standards.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Real-time AI systems that fail to meet performance requirements in production can disrupt critical financial services and harm consumers.', 'secure_resilient', 78);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.2-001', 'MAP 2.2', 'The organization maps and documents the complete AI system architecture, including data pipelines, model components, feature engineering, inference services, and monitoring infrastructure.', 'Create comprehensive architecture documentation for each AI system. Include data flow diagrams from source to prediction. Document all model components, feature transformations, and inference pathways. Map dependencies on shared infrastructure and services. Maintain architecture diagrams as living documents updated with each change.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Undocumented AI architecture creates operational risk, impedes troubleshooting, and prevents effective validation and audit.', 'accountable_transparent', 79);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.2-002', 'MAP 2.2', 'System mapping identifies all dependencies on external data sources, APIs, and third-party services, with contingency plans for dependency failures.', 'Catalog all external dependencies for each AI system. Assess reliability and SLAs of each dependency. Develop contingency responses for dependency failures (fallback data sources, cached models, degraded mode operations). Test dependency failure scenarios regularly. Monitor dependency health in real-time.', '{"scaling","full_implementation"}'::TEXT[], 'Unmapped external dependencies create single points of failure that can cascade to AI system outages without warning.', 'secure_resilient', 80);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.2-003', 'MAP 2.2', 'Architecture documentation is maintained at sufficient detail to support regulatory examination, independent validation, and disaster recovery for the AI system.', 'Ensure documentation supports three use cases: examination (regulators can understand system design), validation (independent reviewers can assess appropriateness), and DR (operations can rebuild/restore). Version-control documentation alongside code. Include deployment configurations, environment specifications, and recovery procedures.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Architecture documentation that cannot support examination, validation, or recovery is insufficient for a regulated financial institution.', 'accountable_transparent', 81);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.3-001', 'MAP 2.3', 'The organization identifies and assesses AI-specific scientific and technical limitations for each system, including model uncertainty, known failure modes, and conditions under which the model should not be relied upon.', 'Document known limitations for each AI system. Include: model assumptions and where they break down, data conditions causing unreliable predictions, populations or scenarios where performance is degraded, uncertainty quantification and confidence intervals. Communicate limitations to users and decision-makers. Include limitations in model documentation per SR 11-7.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Users unaware of AI system limitations may rely on outputs in inappropriate contexts, leading to poor decisions and consumer harm.', 'valid_reliable', 82);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.3-002', 'MAP 2.3', 'Technical limitations assessment addresses the explainability constraints of the chosen modeling approach, particularly for complex models used in consumer-facing decisions subject to adverse action requirements.', 'Evaluate explainability constraints for each model type. For complex models (deep learning, ensemble methods), assess whether model-agnostic explanation methods (SHAP, LIME) provide sufficient fidelity for regulatory requirements. Document explainability methodology and its limitations. For credit models, validate that explanation methods produce adverse action reasons consistent with model behavior.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Using models whose decisions cannot be adequately explained in consumer-facing credit decisions violates ECOA and FCRA requirements.', 'explainable_interpretable', 83);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.3-003', 'MAP 2.3', 'Limitations assessments for generative AI systems address hallucination risk, factual accuracy constraints, training data cutoff dates, and potential for generating harmful or non-compliant content.', 'For generative AI systems, conduct specific limitations assessments covering: hallucination rates by content type, factual accuracy limitations, training data recency and gaps, potential for generating biased or harmful content, and susceptibility to prompt injection. Implement guardrails proportionate to identified limitations. Document residual risks accepted.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Generative AI deployed in financial services without limitations assessment risks producing inaccurate financial information, misleading advice, or non-compliant content.', 'valid_reliable', 84);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.1-001', 'MAP 3.1', 'The organization establishes and enforces data quality standards for AI training, validation, and production data, including completeness, accuracy, consistency, timeliness, and representativeness requirements.', 'Define quantitative data quality metrics and thresholds for AI data. Implement automated data quality checks in data pipelines. Monitor data quality continuously for production AI systems. Establish data quality incident processes. Align with enterprise data governance standards. Document data quality assessment results in model documentation.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Poor data quality is the leading cause of AI model failures and a persistent examination finding in model risk management reviews.', 'valid_reliable', 85);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.1-002', 'MAP 3.1', 'Data used in AI systems is assessed for representativeness relative to the target population, with specific analysis of whether historically underserved populations are adequately represented.', 'Analyze training data composition across demographic dimensions. Identify underrepresented populations and assess impact on model performance for those groups. Evaluate whether historical data reflects past discriminatory practices that could bias the model. Implement data augmentation or reweighting strategies where appropriate. Document representativeness analysis in model documentation.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Unrepresentative training data produces models that perform poorly for underserved populations, perpetuating historical inequities in financial services.', 'fair_bias_managed', 86);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.1-003', 'MAP 3.1', 'Data lineage is documented end-to-end for AI systems, tracing data from source through transformation to model input, supporting auditability and regulatory examination.', 'Implement data lineage tracking for AI data pipelines. Document: original data sources, collection methods, transformation logic, feature engineering steps, and final model input specifications. Use automated lineage tools where feasible. Ensure lineage documentation is sufficient for independent reproduction. Review lineage accuracy during validation.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without data lineage, the organization cannot trace model inputs to sources, impeding validation, audit, and incident investigation.', 'accountable_transparent', 87);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.1-004', 'MAP 3.1', 'The organization evaluates and documents the provenance and licensing of third-party and publicly sourced data used in AI systems, ensuring compliance with data usage rights and privacy regulations.', 'Maintain a data provenance registry for AI data sources. Verify licensing and usage rights for third-party data. Assess privacy compliance for data used in AI (CCPA, GLBA, state privacy laws). Evaluate ethical considerations of data sourcing. Document provenance in model documentation. Review data usage rights annually or upon contract renewal.', '{"scaling","full_implementation"}'::TEXT[], 'Using data without proper licensing or in violation of privacy regulations exposes the institution to legal liability and regulatory action.', 'privacy_enhanced', 88);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.2-001', 'MAP 3.2', 'The organization assesses AI training and operational data for embedded biases, including historical discrimination patterns, sampling biases, and proxy variable effects.', 'Conduct systematic bias assessment for AI training data. Test for: correlation between features and protected characteristics (proxy analysis), historical patterns reflecting discriminatory practices (e.g., redlining in mortgage data), sampling biases that underrepresent populations, and labeling biases in supervised learning data. Document findings and remediation strategies.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Biased training data produces biased AI outputs — a primary mechanism for algorithmic discrimination in financial services.', 'fair_bias_managed', 89);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.2-002', 'MAP 3.2', 'For AI used in credit decisioning, the organization evaluates all input features for potential proxy discrimination, particularly features correlated with race, ethnicity, national origin, or other protected characteristics.', 'Conduct proxy variable analysis for all credit model features. Quantify correlation between each feature and protected characteristics. Evaluate whether proxy features provide legitimate predictive value versus merely encoding protected class information. Consult with fair lending compliance and legal on borderline features. Document analysis and feature selection rationale.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Features that proxy for protected characteristics in credit models create disparate impact liability and are a primary focus of CFPB and DOJ fair lending examinations.', 'fair_bias_managed', 90);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.2-003', 'MAP 3.2', 'Data bias assessment methodologies and findings are reviewed by independent model risk management and fair lending compliance functions before model approval.', 'Require second-line review of data bias assessments. MRM validates methodology and technical rigor. Fair lending compliance evaluates regulatory implications of findings. Joint sign-off required before model can proceed through development gates. Document review findings and any conditions imposed. Escalate unresolved disagreements to governance committee.', '{"scaling","full_implementation"}'::TEXT[], 'First-line bias assessments without independent review may underestimate bias risk due to confirmation bias or insufficient fair lending expertise.', 'fair_bias_managed', 91);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.3-001', 'MAP 3.3', 'The organization classifies AI-related data according to its sensitivity and applies data protection controls commensurate with classification, including encryption, access controls, and retention policies.', 'Apply enterprise data classification standards to AI data. Classify training data, model parameters, feature stores, and inference logs by sensitivity level. Implement encryption at rest and in transit for sensitive AI data. Enforce least-privilege access controls. Define retention and disposal policies per regulatory requirements (GLBA, state laws). Secure model artifacts as confidential.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI data that is unclassified or under-protected creates privacy and security risks, potentially violating GLBA, CCPA, and other data protection requirements.', 'privacy_enhanced', 92);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.3-002', 'MAP 3.3', 'AI systems that process personally identifiable information (PII) or nonpublic personal information (NPI) implement privacy-preserving techniques and comply with applicable privacy regulations.', 'Inventory PII/NPI usage across AI systems. Implement data minimization — use only PII necessary for the AI purpose. Apply privacy-preserving techniques where feasible (anonymization, pseudonymization, differential privacy, federated learning). Ensure compliance with GLBA, CCPA/CPRA, and state privacy laws. Conduct privacy impact assessments for AI systems processing sensitive data.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems processing PII without privacy controls risk data breaches, regulatory penalties, and erosion of consumer trust.', 'privacy_enhanced', 93);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.3-003', 'MAP 3.3', 'Controls prevent AI training data and model outputs from being inadvertently exposed through model inversion, membership inference, or data extraction attacks.', 'Assess AI systems for data leakage vulnerabilities. Implement controls against: model inversion attacks (reconstructing training data from model outputs), membership inference attacks (determining if specific data was in training set), and data extraction from generative AI. Apply output perturbation, access rate limiting, and monitoring for anomalous query patterns.', '{"scaling","full_implementation"}'::TEXT[], 'AI models that leak training data through inference expose sensitive financial and personal information, violating privacy obligations.', 'privacy_enhanced', 94);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.4-001', 'MAP 3.4', 'The organization evaluates the suitability and limitations of AI training data relative to the intended use case, including temporal relevance, geographic coverage, and domain applicability.', 'Assess training data fitness for the specific AI use case. Evaluate temporal coverage — ensure data spans relevant economic cycles for financial models. Assess geographic relevance to the institution''s market footprint. Verify domain applicability (e.g., retail banking data for retail banking AI). Document data suitability assessment and residual limitations.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Training data unsuitable for the use case produces unreliable models that may fail unpredictably when encountering real-world conditions.', 'valid_reliable', 95);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.4-002', 'MAP 3.4', 'For credit risk AI models, training data includes representation across economic cycles (expansion, contraction, recovery) to ensure model robustness through varying macroeconomic conditions.', 'Ensure credit model training data spans at least one full economic cycle. Include stress period data (e.g., 2008-2009, COVID-2020). Assess model sensitivity to macroeconomic conditions through scenario analysis. Supplement limited-period data with synthetic stress scenarios where necessary. Align with CCAR/DFAST stress testing data standards.', '{"scaling","full_implementation"}'::TEXT[], 'Credit AI models trained only on benign economic data fail during downturns, precisely when accurate risk assessment is most critical.', 'valid_reliable', 96);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.4-003', 'MAP 3.4', 'Data suitability assessment for AI includes evaluation of label quality for supervised learning, ensuring labels are accurate, consistent, and free from systematic bias.', 'Assess label quality for supervised learning AI systems. Evaluate labeling methodology and quality control processes. Test for inter-rater reliability where human labeling is used. Identify potential label biases (e.g., historical approval bias in credit data, investigation bias in fraud labels). Document label quality assessment and known limitations.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Poor label quality silently corrupts supervised learning models, producing systematically biased outputs that appear technically valid.', 'valid_reliable', 97);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.5-001', 'MAP 3.5', 'The organization establishes data governance processes specific to AI, including data access approval, usage tracking, and compliance with data usage agreements for AI training and inference.', 'Extend enterprise data governance to address AI-specific needs. Implement AI data access approval workflows. Track data usage across AI systems to ensure compliance with usage agreements and regulatory requirements. Maintain data usage logs for audit purposes. Coordinate with data stewards and data owners on AI data requests.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Ungoverned AI data usage risks violating data usage agreements, privacy regulations, and internal data governance standards.', 'accountable_transparent', 98);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.5-002', 'MAP 3.5', 'Data retention and disposal for AI systems complies with regulatory record-keeping requirements while managing storage costs and privacy obligations.', 'Define AI data retention policies aligned with regulatory requirements (7-year minimum for many banking records). Address retention of training data, model artifacts, inference logs, and monitoring data. Implement secure disposal processes for expired AI data. Balance retention requirements with privacy obligations (right to deletion). Document retention schedules in model documentation.', '{"scaling","full_implementation"}'::TEXT[], 'Improper data retention or premature disposal may violate banking record-keeping requirements or impede regulatory examination.', 'privacy_enhanced', 99);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.5-003', 'MAP 3.5', 'Feature stores and shared data assets used across multiple AI systems are governed with version control, access management, and impact analysis capabilities.', 'Implement governance for shared AI data assets (feature stores, embeddings, reference data). Enforce version control for feature definitions. Maintain access controls and usage logging. Conduct impact analysis before modifying shared features to assess downstream effects on dependent AI systems. Establish change management processes for shared data assets.', '{"scaling","full_implementation"}'::TEXT[], 'Ungoverned shared data assets create hidden dependencies where changes to one feature can silently degrade multiple AI systems.', 'valid_reliable', 100);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-4.1-001', 'MAP 4.1', 'The organization maps AI systems to specific business processes and decisions they support, maintaining traceability from AI output to business action.', 'Create a mapping of AI systems to business processes, decisions, and products they support. Document the role of AI in each decision (advisory, augmenting, autonomous). Maintain traceability from AI predictions to downstream business actions. Enable analysis of business impact when AI systems change or fail. Update mappings when AI system use expands.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without clear mapping of AI to business processes, the organization cannot assess the full impact of AI changes or failures on operations.', 'accountable_transparent', 101);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-4.1-002', 'MAP 4.1', 'Business process owners are engaged in AI system design and monitoring to ensure AI outputs align with business intent and regulatory requirements for the processes they support.', 'Require business process owner involvement throughout the AI lifecycle. Business owners validate that AI outputs align with business intent. Include business owners in monitoring review and threshold-setting. Ensure business owners understand AI system limitations and failure modes. Define business owner responsibilities in the RACI for each AI system.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems developed without business process owner engagement may produce technically correct outputs that are operationally inappropriate or misaligned with business goals.', 'valid_reliable', 102);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-4.1-003', 'MAP 4.1', 'For AI embedded in regulatory compliance processes (BSA/AML, sanctions screening, fair lending monitoring), the mapping includes specific regulatory requirements the AI supports and how compliance is verified.', 'Document the regulatory requirements addressed by AI in compliance processes. Map AI capabilities to specific regulatory obligations (e.g., BSA suspicious activity detection, OFAC sanctions screening, HMDA fair lending analysis). Define how AI contributions to compliance are validated. Ensure compliance officers can explain AI role to examiners. Maintain fallback compliance processes.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI in compliance processes that fails silently or is poorly understood by compliance staff creates regulatory compliance risk.', 'accountable_transparent', 103);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-4.2-001', 'MAP 4.2', 'The organization assesses and documents the degree of human oversight and intervention capability for each AI system, ensuring appropriate human-in-the-loop or human-on-the-loop controls based on risk level.', 'Define the human oversight model for each AI system (human-in-the-loop, human-on-the-loop, or human-in-command). Align oversight level with risk tier — higher risk requires more direct human involvement. Ensure human reviewers have sufficient expertise and information to exercise meaningful oversight. Test override mechanisms regularly. Document oversight model in model documentation.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Insufficient human oversight of AI allows errors to propagate undetected, while excessive oversight negates AI efficiency benefits.', 'accountable_transparent', 104);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-4.2-002', 'MAP 4.2', 'Human override capabilities are implemented and tested for all high-risk AI systems, with kill switches or circuit breakers that can halt AI processing in emergency situations.', 'Implement kill switch capabilities for all high-risk AI systems. Test override mechanisms under realistic conditions, including high-volume scenarios. Define clear procedures for when and how to invoke overrides. Ensure override capabilities are accessible to authorized personnel 24/7. Log all override events for post-incident review. Practice override procedures in business continuity exercises.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'High-risk AI systems without tested override capabilities cannot be safely halted during adverse events, potentially amplifying harm.', 'safe', 105);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-4.2-003', 'MAP 4.2', 'The organization monitors the quality and consistency of human oversight decisions to detect automation bias, alert fatigue, and degradation in human review effectiveness.', 'Track metrics on human oversight quality: override rates, review times, consistency across reviewers, and agreement with AI recommendations. Monitor for automation bias signals (rubber-stamping AI outputs). Address alert fatigue by optimizing AI system thresholds to reduce false positives. Provide periodic training to human reviewers. Rotate reviewers to prevent complacency.', '{"scaling","full_implementation"}'::TEXT[], 'Human oversight that degrades into rubber-stamping provides false assurance while offering no actual risk mitigation.', 'accountable_transparent', 106);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.1-001', 'MEASURE 1.1', 'The organization establishes a measurement and monitoring framework for AI systems that defines metrics, thresholds, frequency, and escalation procedures aligned with model risk management expectations.', 'Develop a comprehensive AI measurement framework. Define standard and system-specific metrics. Set quantitative thresholds with traffic-light indicators (green/amber/red). Specify monitoring frequency by risk tier. Define escalation procedures for threshold breaches. Align with SR 11-7 ongoing monitoring expectations. Document framework and obtain governance committee approval.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems without structured monitoring frameworks operate on faith rather than evidence, accumulating undetected risk.', 'valid_reliable', 107);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.1-002', 'MEASURE 1.1', 'Monitoring metrics cover the full spectrum of AI risk dimensions: performance accuracy, fairness/bias, data quality, operational stability, security, and business outcome alignment.', 'Define metrics across all risk dimensions for each AI system. Performance: accuracy, precision, recall, AUC. Fairness: demographic parity, equalized odds, adverse impact ratios. Data quality: completeness, drift, freshness. Operational: latency, availability, error rates. Security: anomalous access, adversarial inputs. Business: outcome alignment, value realization. Customize by use case.', '{"scaling","full_implementation"}'::TEXT[], 'Narrow monitoring focused only on accuracy misses degradation in fairness, stability, or security that represents material risk.', 'valid_reliable', 108);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.1-003', 'MEASURE 1.1', 'The measurement framework includes provisions for measuring AI system performance under stressed conditions, using scenario analysis consistent with enterprise stress testing practices.', 'Incorporate stress testing into AI measurement. Define stress scenarios relevant to each AI system (economic downturn, market volatility, data disruption, adversarial attack). Measure performance degradation under stress. Compare to predefined robustness thresholds. Align scenarios with CCAR/DFAST stress testing where applicable. Report stress test results to governance committee.', '{"scaling","full_implementation"}'::TEXT[], 'AI systems that appear healthy in normal conditions may fail catastrophically under stress, when reliable performance is most critical.', 'valid_reliable', 109);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.2-001', 'MEASURE 1.2', 'The organization implements automated, continuous monitoring of AI system performance in production, with real-time alerting for metric threshold breaches.', 'Deploy automated monitoring for all production AI systems. Implement real-time data ingestion from model inference logs. Calculate performance metrics on rolling windows appropriate to the use case. Configure threshold-based alerts with appropriate severity levels. Route alerts to system owners and monitoring teams. Ensure monitoring infrastructure has its own availability SLAs.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Manual or periodic-only monitoring misses rapid performance degradation, allowing harmful AI outputs to persist before detection.', 'valid_reliable', 110);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.2-002', 'MEASURE 1.2', 'Model performance monitoring includes concept drift and data drift detection, with automated alerts when input data distributions or prediction patterns deviate significantly from baseline.', 'Implement statistical drift detection methods (PSI, KS test, Jensen-Shannon divergence) for both input features and model outputs. Establish baseline distributions from validation data. Set drift thresholds by feature importance and risk tier. Alert when drift exceeds thresholds. Investigate root causes of detected drift. Trigger revalidation when drift is material.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Undetected drift silently degrades model accuracy, potentially producing systematically wrong predictions before periodic reviews catch the issue.', 'valid_reliable', 111);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.2-003', 'MEASURE 1.2', 'Monitoring systems are designed to be resilient and independent from the AI systems they monitor, preventing correlated failures that could blind the organization to AI system issues.', 'Deploy monitoring infrastructure with separation from production AI systems. Use independent compute resources and data storage. Implement monitoring-of-monitoring to detect monitoring failures. Ensure monitoring continues during AI system outages or degradation. Define fallback monitoring procedures for monitoring system failures.', '{"scaling","full_implementation"}'::TEXT[], 'Monitoring systems that share infrastructure with production AI can fail simultaneously, creating blind spots during the incidents they are designed to detect.', 'secure_resilient', 112);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.3-001', 'MEASURE 1.3', 'Internal audit conducts periodic independent assessments of AI measurement and monitoring effectiveness, verifying that monitoring controls operate as designed and metrics accurately reflect AI system health.', 'Include AI monitoring effectiveness in the audit plan. Verify: monitoring coverage of all production AI systems, accuracy of metric calculations, appropriateness of thresholds, timeliness of alerts, adequacy of response to threshold breaches. Test monitoring end-to-end with simulated scenarios. Report findings to audit committee. Track remediation of identified gaps.', '{"scaling","full_implementation"}'::TEXT[], 'Unaudited AI monitoring may provide false assurance through misconfigured metrics, inappropriate thresholds, or ignored alerts.', 'accountable_transparent', 113);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.3-002', 'MEASURE 1.3', 'The organization conducts periodic benchmarking of AI measurement approaches against regulatory expectations, industry best practices, and peer institution capabilities.', 'Benchmark AI monitoring practices annually against: regulatory guidance (SR 11-7, OCC bulletins), industry frameworks (CRI FS AI RMF), and peer practices (via industry forums). Identify gaps and improvement opportunities. Prioritize enhancements based on risk impact. Report benchmarking results to governance committee. Adjust monitoring practices based on findings.', '{"full_implementation"}'::TEXT[], 'Static monitoring practices that do not evolve with industry standards become insufficient as regulatory expectations advance.', 'accountable_transparent', 114);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-1.3-003', 'MEASURE 1.3', 'External and internal model validators independently assess the adequacy of performance metrics, monitoring thresholds, and ongoing monitoring processes as part of the model validation cycle.', 'Include monitoring assessment in model validation scope per SR 11-7. Validators review: appropriateness of selected metrics for the use case, statistical validity of monitoring methods, reasonableness of thresholds, adequacy of monitoring frequency, and effectiveness of escalation responses. Challenge metrics that may mask performance issues for specific populations. Document validation findings.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Model validation that does not assess monitoring adequacy leaves a critical gap in the model risk management lifecycle.', 'valid_reliable', 115);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.1-001', 'MEASURE 2.1', 'The organization validates AI system accuracy, precision, recall, and other statistical performance metrics against predefined thresholds, using appropriate holdout data and validation methodologies.', 'Implement rigorous validation using proper holdout strategies (temporal splits for time-series, stratified sampling). Calculate standard metrics: accuracy, precision, recall, F1, AUC-ROC, calibration. Compare to predefined thresholds and challenger benchmarks. Validate on recent data to ensure relevance. Document methodology per SR 11-7 effective challenge requirements.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Inadequate validation methodology produces unreliable performance assessments, potentially approving underperforming models for production use.', 'valid_reliable', 116);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.1-002', 'MEASURE 2.1', 'Model validation includes assessment of out-of-sample and out-of-time performance to verify that AI systems generalize appropriately beyond training data.', 'Require out-of-sample testing for all AI models. For time-series and financial models, require out-of-time validation using data from periods not in training. Test performance stability across data segments. Compare in-sample to out-of-sample metrics to detect overfitting. Use walk-forward validation where appropriate. Document generalization assessment thoroughly.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI models that perform well only on training data but fail to generalize are unreliable in production and create false confidence in predicted outcomes.', 'valid_reliable', 117);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.1-003', 'MEASURE 2.1', 'Performance validation disaggregates results across relevant demographic groups, geographic regions, and customer segments to identify differential performance that could indicate bias or unfairness.', 'Segment validation results by: protected demographic characteristics (race, gender, age, national origin), geographic region (urban/rural, CRA assessment areas), and customer segments (income level, product type). Identify segments where performance falls below thresholds. Assess whether differential performance creates disparate impact. Document segmented results and remediation plans.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Aggregate performance metrics can mask poor performance for specific populations, resulting in discriminatory outcomes that violate fair lending requirements.', 'fair_bias_managed', 118);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.2-001', 'MEASURE 2.2', 'The organization conducts regular model validation for all AI systems at a frequency commensurate with risk tier, with annual validation required for high-risk models and triennial for low-risk models.', 'Establish a risk-based validation schedule. High-risk/critical models: annual full validation. Medium-risk: biennial full validation with annual monitoring review. Low-risk: triennial validation with annual monitoring. Trigger ad hoc revalidation for material changes, performance degradation, or regulatory concerns. Track validation schedule compliance as a key risk metric.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Infrequent validation allows model degradation to persist undetected, while excessive validation wastes scarce MRM resources on low-risk systems.', 'valid_reliable', 119);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.2-002', 'MEASURE 2.2', 'Model validation is performed by independent parties with no involvement in model development, consistent with SR 11-7 requirements for effective challenge.', 'Ensure validation independence per SR 11-7. Validators must have no reporting relationship to model developers. Provide validators with full access to model documentation, code, and data. Enable effective challenge through sufficient expertise, authority, and incentive to identify issues. Use external validators to supplement internal capacity or for specialized model types.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Validation without independence fails to provide effective challenge, a core requirement of SR 11-7 and a frequent examination finding.', 'valid_reliable', 120);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.2-003', 'MEASURE 2.2', 'Validation findings are documented, risk-rated, and tracked to remediation with defined timelines and accountable owners, with unresolved high-severity findings escalated to senior management.', 'Require written validation reports with findings rated by severity (high, medium, low). Assign each finding an accountable owner and remediation timeline. Track findings in a centralized issue management system. Escalate past-due or high-severity findings to governance committee. Report validation finding trends to the board. Verify remediation effectiveness through follow-up testing.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Validation findings that are not tracked and remediated represent identified risks that the organization has chosen to ignore.', 'accountable_transparent', 121);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.3-001', 'MEASURE 2.3', 'AI model outputs include quantified measures of prediction confidence or uncertainty that enable users to calibrate their reliance on model predictions.', 'Implement confidence scoring or uncertainty quantification for AI model outputs. Use calibrated probabilities, prediction intervals, or ensemble disagreement measures. Communicate uncertainty to end users in an understandable format. Define confidence thresholds below which human review is required. Validate calibration accuracy during model validation.', '{"scaling","full_implementation"}'::TEXT[], 'AI predictions without confidence measures are treated as equally reliable, leading users to act on uncertain predictions as if they were definitive.', 'valid_reliable', 122);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.3-002', 'MEASURE 2.3', 'For AI used in credit risk quantification (PD, LGD, EAD models), uncertainty measures support capital adequacy assessments and stress testing with quantified model risk adjustments.', 'Quantify estimation uncertainty for credit risk AI models. Incorporate model uncertainty into capital calculations as conservative adjustments. Use uncertainty measures in stress testing to assess model reliability under adverse scenarios. Compare AI model uncertainty to traditional model uncertainty. Document uncertainty methodology for regulatory review. Align with Basel and CCAR requirements.', '{"full_implementation"}'::TEXT[], 'Credit risk AI models without uncertainty quantification may understate capital requirements, creating safety and soundness concerns.', 'valid_reliable', 123);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.3-003', 'MEASURE 2.3', 'The organization validates the accuracy of uncertainty estimates, ensuring that stated confidence levels match observed accuracy (calibration) across relevant data segments.', 'Test calibration of confidence estimates: predicted probabilities should match observed frequencies. Use reliability diagrams and calibration metrics (Brier score, ECE). Test calibration across demographic groups and data segments. Recalibrate models when calibration degrades. Include calibration assessment in validation scope.', '{"scaling","full_implementation"}'::TEXT[], 'Miscalibrated confidence estimates mislead users about prediction reliability, potentially leading to over-reliance on uncertain outputs.', 'valid_reliable', 124);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.4-001', 'MEASURE 2.4', 'The organization tests AI systems for robustness against input perturbations, distributional shifts, and edge cases that reflect realistic production conditions in financial services.', 'Conduct robustness testing using: adversarial input perturbations, synthetic distributional shifts (simulating economic regime changes), boundary and edge case analysis, missing data scenarios, and extreme value testing. Define acceptable degradation bounds. Test with financial services-specific scenarios (rate shocks, liquidity events, counterparty failures). Document results and residual risks.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems not tested for robustness may produce erratic outputs under conditions that differ from training, potentially amplifying financial stress.', 'valid_reliable', 125);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.4-002', 'MEASURE 2.4', 'Robustness testing for BSA/AML AI models includes evaluation against known typologies, emerging financial crime patterns, and adversarial evasion tactics used by sophisticated bad actors.', 'Test BSA/AML AI against: known money laundering and terrorist financing typologies, emerging patterns from FinCEN advisories and industry intelligence, adversarial evasion scenarios (structuring, layering, shell company networks), and synthetic suspicious activity patterns. Measure detection rates across typology categories. Assess vulnerability to evasion tactics. Update test cases as new typologies emerge.', '{"scaling","full_implementation"}'::TEXT[], 'BSA/AML AI that cannot detect known typologies or is easily evaded fails its core purpose and creates BSA compliance violations.', 'secure_resilient', 126);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.4-003', 'MEASURE 2.4', 'The organization conducts regression testing for AI systems after any model update, retraining, or infrastructure change to verify that existing performance is maintained.', 'Implement automated regression testing suites for AI systems. Execute regression tests after any change: model retraining, feature engineering updates, infrastructure changes, dependency updates. Compare post-change performance to pre-change baselines. Define regression thresholds that trigger rollback. Include fairness metrics in regression testing. Maintain regression test documentation.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Changes to AI systems without regression testing may inadvertently degrade performance, introducing errors that affect consumers and business operations.', 'valid_reliable', 127);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.5-001', 'MEASURE 2.5', 'The organization implements comprehensive fairness testing for AI systems that affect consumers, measuring disparate impact across protected class attributes using multiple fairness metrics.', 'Implement fairness testing using multiple metrics: adverse impact ratio (four-fifths rule), demographic parity difference, equalized odds difference, predictive parity, and calibration across groups. Test across protected attributes: race, ethnicity, gender, age, national origin, disability, and marital status. Document methodology, results, and remediation for any identified disparities. Obtain fair lending compliance sign-off.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems deployed without comprehensive fairness testing risk producing discriminatory outcomes, a primary focus of CFPB enforcement.', 'fair_bias_managed', 128);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.5-002', 'MEASURE 2.5', 'Fairness testing uses BISG, BIFSG, or other validated proxy methodologies where self-reported demographic data is unavailable, consistent with CFPB and DOJ fair lending examination approaches.', 'Implement validated proxy methodologies for protected characteristic estimation. Use BISG (Bayesian Improved Surname Geocoding) or BIFSG for race/ethnicity proxying. Document proxy methodology, validation, and known limitations. Align proxy approaches with CFPB examination methodologies. Update proxy models with latest census data. Consider supplementing with additional data sources to improve accuracy.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Fair lending analysis without validated proxy methodologies is incomplete and may fail to detect discrimination that regulators would identify in examination.', 'fair_bias_managed', 129);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.5-003', 'MEASURE 2.5', 'When fairness testing identifies disparate impact, the organization conducts less discriminatory alternative analysis to determine whether model modifications can reduce disparity while maintaining acceptable performance.', 'Implement LDA (less discriminatory alternative) analysis when disparate impact is detected. Test alternative model specifications, feature sets, and thresholds. Evaluate trade-offs between fairness improvement and performance. Document alternatives considered, results, and rationale for selected approach. Align with CFPB expectations for LDA analysis in credit models. Retain analysis for regulatory review.', '{"scaling","full_implementation"}'::TEXT[], 'Failing to explore less discriminatory alternatives after identifying disparate impact demonstrates insufficient effort to mitigate bias and increases enforcement risk.', 'fair_bias_managed', 130);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.6-001', 'MEASURE 2.6', 'The organization assesses and measures AI system explainability, ensuring that model outputs can be understood and explained at a level appropriate for the decision context and audience.', 'Evaluate explainability for each AI system. Determine required explanation level by audience: consumers (plain language adverse action reasons), operators (feature importance and decision logic), regulators (full model methodology), and validators (mathematical detail). Implement appropriate explainability methods (SHAP, LIME, attention visualization). Validate that explanations accurately represent model behavior.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems that cannot be explained at the required level for their context fail regulatory expectations and erode user and consumer trust.', 'explainable_interpretable', 131);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.6-002', 'MEASURE 2.6', 'For credit decisioning AI, explainability methods are validated to ensure adverse action reason codes accurately reflect the model''s actual decision factors, meeting ECOA and FCRA requirements.', 'Validate that explanation methods produce adverse action reasons consistent with model behavior. Test explanation accuracy using known input perturbations. Compare reason code rankings to actual feature importance. Verify that reason codes are specific and actionable for consumers. Conduct periodic testing with new data. Document validation methodology and results for regulatory examination.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Inaccurate adverse action reason codes from AI credit models violate ECOA and FCRA, exposing the institution to enforcement action and litigation.', 'explainable_interpretable', 132);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.6-003', 'MEASURE 2.6', 'The organization measures the fidelity of AI explanation methods to the underlying model, quantifying how accurately post-hoc explanations reflect actual model decision-making.', 'Quantify explanation fidelity using metrics such as: local fidelity of surrogate explanations, stability of explanations across similar inputs, and consistency between global and local explanations. Test explanation methods against known ground truth in controlled scenarios. Flag low-fidelity explanations for enhanced human review. Research and adopt improved explanation methods as the field advances.', '{"scaling","full_implementation"}'::TEXT[], 'Low-fidelity explanations create an illusion of transparency while potentially misrepresenting model behavior to users and regulators.', 'explainable_interpretable', 133);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.7-001', 'MEASURE 2.7', 'The organization implements security testing for AI systems, including vulnerability assessment, penetration testing, and adversarial robustness evaluation specific to AI/ML attack vectors.', 'Conduct AI-specific security testing covering: adversarial input attacks (evasion, poisoning), model extraction and theft, prompt injection (for generative AI), data exfiltration through model queries, and supply chain attacks on AI dependencies. Include AI systems in enterprise penetration testing scope. Engage AI security specialists for advanced testing. Remediate findings per enterprise vulnerability management standards.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems not tested for AI-specific security vulnerabilities are exposed to novel attack vectors that traditional security testing does not address.', 'secure_resilient', 134);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.7-002', 'MEASURE 2.7', 'Security controls for AI systems protect model confidentiality, integrity, and availability, including secure model storage, access controls, and tamper detection.', 'Implement layered security for AI assets. Protect model confidentiality: encrypt model files, restrict access to model parameters, monitor for model extraction. Ensure integrity: implement model signing, detect unauthorized modifications, verify model artifacts before deployment. Maintain availability: redundant model serving, DDoS protection, graceful degradation. Align with FFIEC cybersecurity guidance.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems with compromised confidentiality, integrity, or availability can produce manipulated outputs, be stolen by competitors, or deny service to customers.', 'secure_resilient', 135);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.7-003', 'MEASURE 2.7', 'The organization monitors AI systems for indicators of adversarial manipulation, including anomalous input patterns, unexpected output distributions, and unauthorized access attempts.', 'Implement runtime adversarial monitoring: detect anomalous input patterns that may indicate evasion attempts, monitor output distributions for signs of model manipulation, alert on unusual API access patterns suggesting extraction attacks, and flag prompt injection attempts for generative AI. Integrate with enterprise security operations center (SOC). Define AI-specific incident response playbooks.', '{"scaling","full_implementation"}'::TEXT[], 'Without adversarial monitoring, AI systems may be silently manipulated by malicious actors to produce harmful outputs or leak sensitive data.', 'secure_resilient', 136);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.8-001', 'MEASURE 2.8', 'The organization conducts privacy impact assessments for AI systems that process personal data, evaluating privacy risks across the AI lifecycle including data collection, training, inference, and retention.', 'Require PIAs for AI systems processing PII/NPI. Assess privacy risks at each lifecycle stage: data collection (consent, purpose limitation), training (data minimization, anonymization), inference (re-identification risk, output privacy), and retention (storage security, disposal). Align with GLBA, CCPA/CPRA requirements. Coordinate with the privacy office. Document PIA results and mitigations.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems create novel privacy risks that traditional PIAs may not address, including re-identification from aggregate data and training data memorization.', 'privacy_enhanced', 137);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.8-002', 'MEASURE 2.8', 'AI systems comply with consumer data rights under applicable privacy laws, including rights to access, correction, deletion, and opt-out of automated decision-making where required.', 'Map AI data processing to consumer rights requirements under GLBA, CCPA/CPRA, and state privacy laws. Implement technical capabilities to honor access, correction, and deletion requests for AI training and inference data. Address right to opt-out of automated decision-making where applicable. Define processes for handling consumer rights requests that affect AI systems. Document compliance procedures.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems that cannot honor consumer data rights violate privacy regulations and undermine consumer trust in the institution.', 'privacy_enhanced', 138);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.8-003', 'MEASURE 2.8', 'The organization evaluates and mitigates the risk of AI systems memorizing or revealing sensitive training data through model outputs, particularly for generative AI systems.', 'Test AI systems for training data memorization using extraction attacks and canary-based detection. Implement differential privacy techniques during training where feasible. Filter model outputs for sensitive data patterns (SSNs, account numbers, PII). Monitor generative AI outputs for verbatim reproduction of training data. Apply output sanitization as a defense-in-depth measure.', '{"scaling","full_implementation"}'::TEXT[], 'AI systems that memorize and reveal training data create data breach risk, potentially exposing customer financial information through model outputs.', 'privacy_enhanced', 139);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.9-001', 'MEASURE 2.9', 'The organization measures and manages the environmental and computational costs of AI systems, including energy consumption, carbon footprint, and infrastructure costs proportionate to business value delivered.', 'Track computational resource consumption for AI training and inference. Estimate energy usage and carbon footprint of AI operations. Evaluate efficiency of model architectures and training approaches. Optimize resource usage through model compression, efficient serving, and appropriate hardware selection. Include environmental costs in AI business case analysis. Report on AI sustainability metrics.', '{"scaling","full_implementation"}'::TEXT[], 'Unconstrained AI computational costs create financial waste and increasingly attract regulatory and stakeholder scrutiny on environmental grounds.', 'accountable_transparent', 140);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.9-002', 'MEASURE 2.9', 'AI system design and model selection consider efficiency alongside accuracy, favoring computationally efficient approaches where performance differences are not material to business outcomes.', 'Include computational efficiency as an evaluation criterion in model selection. Compare model accuracy against resource consumption. Favor simpler models when performance differences are marginal. Implement model compression and distillation for deployment. Use appropriate model sizes — avoid deploying larger models than necessary. Document efficiency trade-offs in model documentation.', '{"scaling","full_implementation"}'::TEXT[], 'Defaulting to the largest available models without efficiency analysis wastes resources and increases operational complexity without proportionate benefit.', 'accountable_transparent', 141);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.9-003', 'MEASURE 2.9', 'The organization evaluates the broader societal impacts of its AI systems, including effects on employment, financial inclusion, and community well-being, particularly in CRA assessment areas.', 'Assess societal impacts of AI systems beyond direct business outcomes. Evaluate effects on: employment (automation displacement, workforce transformation), financial inclusion (access to credit, banking services), and community impact (CRA assessment areas, underserved populations). Integrate societal impact assessment into AI governance processes. Report on positive and negative societal outcomes.', '{"full_implementation"}'::TEXT[], 'Financial institutions'' AI deployments can have significant societal impacts that, if negative, create reputational risk and regulatory concern, particularly related to CRA obligations.', 'fair_bias_managed', 142);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.10-001', 'MEASURE 2.10', 'The organization measures and reports on AI system availability, reliability, and operational performance against defined service level objectives.', 'Define SLOs for AI system availability, latency, throughput, and error rates. Implement comprehensive operational monitoring. Track: uptime, response times, queue depths, error rates, and resource utilization. Report SLO compliance to system owners and governance committee. Trigger incident response when SLOs are breached. Conduct capacity planning to maintain performance as usage grows.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems that are unreliable or unavailable disrupt business operations and degrade customer experience, potentially violating service commitments.', 'valid_reliable', 143);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.10-002', 'MEASURE 2.10', 'Operational performance measurement for AI in customer-facing applications includes customer experience metrics (response time, accuracy of responses, customer satisfaction) alongside technical metrics.', 'Define customer-facing AI metrics including: end-to-end response time, answer accuracy and completeness, customer satisfaction scores, escalation rates, and task completion rates. Track customer complaints and feedback specific to AI interactions. Correlate customer experience metrics with technical performance. Use A/B testing to measure AI impact on customer outcomes.', '{"scaling","full_implementation"}'::TEXT[], 'Technically performant AI that delivers poor customer experience fails to create business value and may harm the institution''s competitive position.', 'valid_reliable', 144);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.10-003', 'MEASURE 2.10', 'The organization tracks and manages AI model retraining frequency and deployment velocity, ensuring models remain current while maintaining stability and control.', 'Establish guidelines for model retraining frequency by use case and risk tier. Monitor model freshness as a metric — time since last retraining. Balance freshness against stability and validation requirements. Implement deployment velocity metrics to track time from model update to production. Ensure retraining and deployment processes maintain governance controls (testing, validation, approval).', '{"scaling","full_implementation"}'::TEXT[], 'Models that are retrained too infrequently become stale, while models retrained too frequently may introduce instability and bypass governance controls.', 'valid_reliable', 145);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.11-001', 'MEASURE 2.11', 'The organization evaluates AI system performance in the context of human-AI teaming, measuring whether AI augmentation improves decision quality compared to purely human or purely automated processes.', 'Measure decision quality for human-AI teams compared to baselines. Track: accuracy of AI-augmented decisions vs. unassisted human decisions, time-to-decision with AI augmentation, consistency of decisions across operators, and appropriate override rates. Conduct periodic controlled comparisons. Identify where human-AI teaming adds value vs. where it creates friction. Optimize the interaction model based on evidence.', '{"scaling","full_implementation"}'::TEXT[], 'Assuming human-AI teaming improves outcomes without measurement may mask situations where AI augmentation actually degrades decision quality.', 'valid_reliable', 146);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.11-002', 'MEASURE 2.11', 'The organization measures and addresses automation bias — the tendency of human operators to defer excessively to AI recommendations — in AI-augmented decision processes.', 'Monitor for automation bias indicators: declining override rates over time, decreased review times suggesting less scrutiny, and agreement rates approaching 100%. Implement countermeasures: require justification for agreement (not just disagreement), rotate AI-assisted and manual reviews, provide training on automation bias. Track bias indicators for each AI-augmented process. Adjust human-AI interaction design to promote appropriate skepticism.', '{"scaling","full_implementation"}'::TEXT[], 'Automation bias converts human-in-the-loop oversight from a control into a rubber stamp, eliminating the independent judgment that human review is intended to provide.', 'accountable_transparent', 147);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.11-003', 'MEASURE 2.11', 'User interface design for AI-augmented decision systems is evaluated for effectiveness in conveying AI confidence, uncertainty, and limitations to human decision-makers.', 'Evaluate UI effectiveness through user studies and decision quality analysis. Assess whether interfaces clearly communicate: AI confidence level, key factors driving the recommendation, known limitations for the specific case, and when to exercise additional scrutiny. Test UI designs with representative users. Iterate based on user feedback and decision quality data. Apply human factors engineering principles.', '{"scaling","full_implementation"}'::TEXT[], 'Poorly designed interfaces that obscure AI uncertainty or present recommendations as definitive undermine informed human oversight.', 'explainable_interpretable', 148);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.1-001', 'MEASURE 3.1', 'The organization conducts regular reviews of AI monitoring results, with defined cadences ranging from daily automated reviews to quarterly governance committee deep dives based on risk tier.', 'Establish tiered monitoring review cadences. Daily: automated alert review and triage. Weekly: system owner performance review. Monthly: MRM monitoring review for high-risk systems. Quarterly: governance committee review of AI monitoring portfolio. Annually: comprehensive monitoring effectiveness assessment. Document review outcomes, decisions, and action items at each level.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Monitoring data that is collected but not reviewed provides no risk management value and creates a false sense of oversight.', 'accountable_transparent', 149);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.1-002', 'MEASURE 3.1', 'Monitoring reviews include assessment of whether AI system outcomes align with original business intent and continue to provide expected value, triggering revalidation or decommissioning when alignment degrades.', 'Include business outcome alignment in monitoring reviews. Compare AI system performance against original business case expectations. Measure value realization (cost savings, accuracy improvement, revenue impact). Identify systems where value has degraded below investment threshold. Trigger revalidation for performance concerns. Recommend decommissioning for systems no longer providing sufficient value.', '{"scaling","full_implementation"}'::TEXT[], 'AI systems that no longer deliver business value consume governance resources and represent opportunity cost that could be redirected to higher-value initiatives.', 'accountable_transparent', 150);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.1-003', 'MEASURE 3.1', 'The organization maintains documentation of all monitoring reviews, findings, decisions, and action items, sufficient to demonstrate ongoing AI oversight to regulators.', 'Document all monitoring review activities in a structured, auditable format. Record: review date, participants, metrics reviewed, findings, decisions, action items with owners and deadlines, and escalations. Maintain documentation in a centralized repository. Ensure documentation is readily retrievable for regulatory examination. Retain monitoring records per regulatory record-keeping requirements.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Undocumented monitoring reviews cannot be demonstrated to regulators, effectively making the oversight invisible to examiners.', 'accountable_transparent', 151);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.2-001', 'MEASURE 3.2', 'AI-related risks are included in the organization''s enterprise risk reporting, with metrics, trends, and commentary integrated into existing risk management information (MIS) for senior management and the board.', 'Integrate AI risk metrics into enterprise risk dashboards. Include: AI inventory growth, risk tier distribution, validation backlog, open findings, performance alerts, incidents, and emerging risks. Provide trend analysis showing direction of travel. Include narrative commentary on material items. Ensure consistency with other enterprise risk reporting. Present at board risk committee meetings.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI risk excluded from enterprise risk reporting creates blind spots for senior management and board, preventing informed oversight.', 'accountable_transparent', 152);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.2-002', 'MEASURE 3.2', 'Risk reporting differentiates between AI system performance metrics and AI governance program metrics, providing visibility into both individual system health and the overall effectiveness of the AI governance framework.', 'Develop two levels of AI risk reporting. System-level: individual model performance, monitoring results, validation status, and issues. Program-level: governance framework effectiveness, policy compliance, training completion, process maturity, and regulatory readiness. Present both levels to governance committee. Ensure board receives program-level view with system-level detail available on request.', '{"scaling","full_implementation"}'::TEXT[], 'Reporting only system-level metrics without program-level assessment prevents assessment of whether the AI governance framework itself is effective.', 'accountable_transparent', 153);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.2-003', 'MEASURE 3.2', 'AI risk reporting includes forward-looking risk indicators and emerging risk assessments, not solely backward-looking performance metrics.', 'Develop leading indicators for AI risk: rate of AI deployment vs. governance capacity, emerging regulatory proposals, technology evolution trends, competitive pressure to deploy AI faster, and talent market trends. Include emerging risk commentary in quarterly reports. Conduct scenario analysis for potential AI risk events. Present forward-looking risk view alongside historical performance.', '{"full_implementation"}'::TEXT[], 'Purely backward-looking AI risk reporting fails to prepare the organization for emerging threats and regulatory changes.', 'accountable_transparent', 154);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.3-001', 'MEASURE 3.3', 'The organization defines and tracks key risk indicators (KRIs) for its AI program, with quantitative thresholds that trigger defined management actions when breached.', 'Define KRIs for the AI program including: percentage of AI systems with current validation, average age of open findings, number of monitoring threshold breaches, AI incident frequency and severity, validation backlog size, and time-to-deploy for model updates. Set amber and red thresholds for each KRI. Define specific management actions for threshold breaches. Report KRI dashboard to governance committee monthly.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without quantitative KRIs, AI risk management operates qualitatively, making it difficult to objectively assess program health and trigger timely intervention.', 'accountable_transparent', 155);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.3-002', 'MEASURE 3.3', 'AI KRIs are calibrated based on historical data and industry benchmarks, with periodic recalibration to reflect changes in the organization''s AI program maturity and regulatory environment.', 'Calibrate KRI thresholds using internal historical performance data, industry benchmarks (from CRI surveys, regulatory reports), and peer comparisons. Avoid thresholds that are so loose they never trigger or so tight they generate excessive false alerts. Recalibrate annually or when material changes occur (new regulations, significant AI program growth, organizational changes). Document calibration methodology.', '{"scaling","full_implementation"}'::TEXT[], 'Poorly calibrated KRIs either fail to detect meaningful risk increases or generate so many false alerts that they are ignored.', 'accountable_transparent', 156);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.3-003', 'MEASURE 3.3', 'KRI trends are analyzed for early warning signals, with root cause analysis conducted when adverse trends are identified before thresholds are breached.', 'Implement trend analysis for all AI KRIs. Use statistical methods to detect trending indicators. Conduct proactive investigation when KRIs show adverse trends, even before thresholds are crossed. Document trend analysis and root cause findings. Present trend analysis in governance reporting. Take preventive action to arrest adverse trends before they become threshold events.', '{"scaling","full_implementation"}'::TEXT[], 'Waiting for KRI threshold breaches to take action means responding to problems that could have been prevented through earlier trend-based intervention.', 'accountable_transparent', 157);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-4.1-001', 'MEASURE 4.1', 'The organization measures the effectiveness of its AI risk mitigation controls, tracking whether implemented controls reduce risk as intended.', 'Define effectiveness measures for each AI risk control. Track: control execution rate (is the control performed as designed?), control efficacy (does the control reduce risk when executed?), and residual risk level after control application. Use control testing to verify effectiveness. Report control effectiveness to governance committee. Remediate ineffective controls promptly.', '{"scaling","full_implementation"}'::TEXT[], 'Controls that are implemented but not measured for effectiveness may provide false assurance while failing to mitigate AI risk.', 'accountable_transparent', 158);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-4.1-002', 'MEASURE 4.1', 'Control effectiveness measurement includes assessment of timeliness — whether risk mitigation actions are executed within required timeframes to prevent harm.', 'Track time-based control metrics: time-to-detect monitoring alerts, time-to-respond to threshold breaches, time-to-remediate validation findings, and time-to-deploy model fixes. Define SLAs for each control activity by risk tier. Measure compliance with SLAs. Escalate SLA breaches per defined procedures. Analyze root causes of timeliness failures.', '{"scaling","full_implementation"}'::TEXT[], 'Controls that eventually work but too slowly allow harmful AI outputs to persist, increasing consumer impact and regulatory exposure.', 'accountable_transparent', 159);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-4.1-003', 'MEASURE 4.1', 'The organization uses control effectiveness data to continuously improve its AI risk management framework, strengthening or replacing controls that prove ineffective.', 'Analyze control effectiveness data to identify improvement opportunities. Replace or supplement controls with low efficacy scores. Investigate root causes of control failures. Implement process improvements based on findings. Share effective control practices across AI teams. Report continuous improvement activities to governance committee. Maintain a control improvement roadmap.', '{"full_implementation"}'::TEXT[], 'Static control frameworks that do not evolve based on effectiveness data become increasingly disconnected from actual risk as the AI program matures.', 'accountable_transparent', 160);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-4.2-001', 'MEASURE 4.2', 'The organization maintains a centralized AI issue and finding management system that tracks all identified AI risks, validation findings, monitoring alerts, and audit observations to closure.', 'Implement a centralized issue tracking system for AI-related findings from all sources: model validation, monitoring, audit, regulatory examination, and self-identified issues. Require: clear issue description, risk rating, accountable owner, root cause analysis, remediation plan, target date, and status tracking. Integrate with enterprise issue management. Generate aging reports and escalate overdue items.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Decentralized or informal issue tracking allows findings to be lost or forgotten, resulting in persistent unresolved risks.', 'accountable_transparent', 161);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-4.2-002', 'MEASURE 4.2', 'AI issues and findings are prioritized using a risk-based methodology, with resolution timelines proportionate to severity and potential consumer impact.', 'Define risk-based prioritization criteria for AI issues. Assign severity levels based on: potential consumer harm, regulatory compliance impact, financial exposure, and operational disruption. Set maximum resolution timelines by severity (e.g., critical: 30 days, high: 60 days, medium: 90 days, low: 180 days). Enforce timelines through governance oversight. Provide interim risk mitigants for issues that cannot be resolved quickly.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without risk-based prioritization, critical AI issues may languish while low-priority items consume remediation resources.', 'accountable_transparent', 162);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-4.2-003', 'MEASURE 4.2', 'Root cause analysis is required for significant AI issues, with findings used to prevent recurrence across the AI program through systemic improvements.', 'Require root cause analysis for all high-severity AI issues and incidents. Use structured RCA methodologies (5 Whys, fishbone, fault tree). Identify systemic factors, not just proximate causes. Determine whether similar issues could affect other AI systems. Implement enterprise-wide preventive actions where applicable. Document RCA results and link to remediation actions.', '{"scaling","full_implementation"}'::TEXT[], 'Fixing symptoms without root cause analysis leads to recurring issues that erode confidence in the AI risk management program.', 'accountable_transparent', 163);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.1-001', 'MANAGE 1.1', 'The organization implements risk treatment plans for all AI systems, selecting appropriate risk responses (mitigate, transfer, accept, avoid) based on risk assessment results and risk appetite.', 'Develop risk treatment plans for each AI system based on risk assessment. Define specific controls to mitigate identified risks. Document residual risk after treatment. Obtain risk acceptance approval at appropriate authority level (system owner for low risk, CRO for high risk). Review treatment plans annually or after material changes. Ensure consistency with enterprise risk treatment standards.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Identified AI risks without defined treatment plans remain unmanaged, creating exposure that the organization has acknowledged but not addressed.', 'accountable_transparent', 164);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.1-002', 'MANAGE 1.1', 'Risk acceptance decisions for AI systems are made at an authority level commensurate with the risk, with formal documentation of the accepted risk, compensating controls, and conditions for re-evaluation.', 'Define risk acceptance authority by risk level. Require formal risk acceptance documentation including: specific risk being accepted, rationale, compensating controls in place, time-bound review conditions, and approver signature. Maintain a risk acceptance register. Review accepted risks at minimum annually. Escalate if conditions change or compensating controls weaken. Report accepted risks to governance committee.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Informal or unauthorized risk acceptance creates hidden exposure and may result in examination findings on governance rigor.', 'accountable_transparent', 165);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.1-003', 'MANAGE 1.1', 'Risk treatment plans for consumer-facing AI include specific consumer harm mitigation measures, including fallback processes, human escalation paths, and remediation procedures for harmed consumers.', 'Define consumer-specific risk mitigations for AI in financial products. Implement: manual fallback processes for AI system failures, human escalation paths for disputed AI decisions, consumer remediation procedures when AI errors cause harm, and proactive notification when material AI errors are discovered. Align with CFPB expectations for consumer protection. Test consumer harm scenarios regularly.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems that harm consumers without defined remediation processes expose the institution to UDAAP liability and regulatory enforcement.', 'safe', 166);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.1-004', 'MANAGE 1.1', 'The organization considers risk transfer mechanisms (insurance, contractual provisions) for AI-related risks where appropriate, particularly for high-severity, low-frequency AI failure scenarios.', 'Evaluate risk transfer options for AI risks. Assess cyber insurance coverage for AI-specific incidents. Negotiate vendor contracts that allocate AI risk appropriately. Consider professional liability coverage for AI-driven financial advice. Evaluate the adequacy of risk transfer relative to potential exposure. Document risk transfer mechanisms in risk treatment plans.', '{"scaling","full_implementation"}'::TEXT[], 'Sole reliance on risk mitigation without considering risk transfer leaves the institution fully exposed to residual AI risks that could be shared.', 'accountable_transparent', 167);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.2-001', 'MANAGE 1.2', 'The organization prioritizes AI risk management activities based on a systematic assessment of risk severity, likelihood, and potential impact, focusing resources on the highest-risk AI systems.', 'Develop a risk-based prioritization framework for AI management activities. Use quantitative risk scoring incorporating severity, likelihood, consumer impact, and regulatory sensitivity. Allocate validation, monitoring, and remediation resources according to priority. Review priorities quarterly as the risk landscape changes. Document prioritization methodology and rationale for resource allocation decisions.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Equal treatment of all AI systems regardless of risk wastes limited governance resources and may leave the highest-risk systems under-managed.', 'accountable_transparent', 168);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.2-002', 'MANAGE 1.2', 'Prioritization considers aggregate and correlated AI risks, not just individual system risks, identifying concentrations and interdependencies that could amplify impact.', 'Assess AI risk at the portfolio level, not just individually. Identify: correlated risk factors across AI systems (shared data sources, common vendors, similar methodologies), concentration risk in critical business functions, and cascade potential where one system''s failure affects others. Include aggregate risk view in governance reporting. Adjust priorities based on portfolio-level analysis.', '{"scaling","full_implementation"}'::TEXT[], 'Individual system risk assessments that ignore correlations and concentrations can dramatically underestimate the organization''s total AI risk exposure.', 'accountable_transparent', 169);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.2-003', 'MANAGE 1.2', 'The organization conducts periodic re-prioritization of AI risk management activities to reflect changes in the threat landscape, regulatory environment, and organizational AI strategy.', 'Review AI risk priorities at minimum quarterly. Triggers for re-prioritization include: new regulatory guidance, examination findings, material incidents (internal or industry), significant AI program changes, and emerging threat intelligence. Communicate priority changes to affected stakeholders. Adjust resource allocations accordingly. Document re-prioritization decisions and rationale.', '{"scaling","full_implementation"}'::TEXT[], 'Static risk priorities that do not adapt to a changing environment lead to misallocated resources and unaddressed emerging risks.', 'accountable_transparent', 170);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.3-001', 'MANAGE 1.3', 'The organization communicates AI risk assessment results, monitoring findings, and governance decisions to relevant internal stakeholders through defined reporting channels.', 'Define reporting channels for AI risk information. Ensure: board and senior management receive strategic AI risk reporting, business line leaders receive operational AI risk information relevant to their systems, technology teams receive technical monitoring data, and compliance/legal receive regulatory risk intelligence. Use existing reporting infrastructure where possible. Tailor format and detail to audience needs.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Poor internal communication of AI risk information leads to uninformed decisions, duplicated efforts, and missed coordination opportunities.', 'accountable_transparent', 171);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.3-002', 'MANAGE 1.3', 'External AI risk communications, including disclosures to regulators, investors, and consumers, are coordinated through governance processes with appropriate legal and compliance review.', 'Establish a process for external AI risk communications. Coordinate disclosures through a central governance function. Require legal review of AI-related disclosures. Ensure consistency across disclosure channels (regulatory filings, investor presentations, consumer notices). Comply with regulatory disclosure requirements. Maintain a log of external AI communications for audit trail.', '{"scaling","full_implementation"}'::TEXT[], 'Uncoordinated external AI communications risk inconsistent messaging, premature disclosure, or failure to meet regulatory notification requirements.', 'accountable_transparent', 172);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.3-003', 'MANAGE 1.3', 'The organization provides transparent disclosure to consumers about AI use in decisions that materially affect them, consistent with regulatory requirements and industry best practices.', 'Develop consumer-facing AI disclosure standards. Disclose AI involvement in: credit decisions, insurance underwriting, fraud alerts, and account management actions. Provide disclosures in plain language at appropriate decision points. Comply with ECOA adverse action, FCRA, and state AI disclosure laws. Balance transparency with IP protection and security considerations. Test consumer comprehension of disclosures.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Opaque AI use in consumer-affecting decisions violates emerging disclosure requirements and erodes consumer trust when discovered.', 'accountable_transparent', 173);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.4-001', 'MANAGE 1.4', 'The organization defines escalation criteria and processes for AI risks that exceed defined thresholds, ensuring timely elevation to appropriate decision-makers.', 'Define clear escalation triggers for AI risks: monitoring threshold breaches, validation finding severity, incident severity, regulatory findings, and policy exceptions. Map escalation paths to governance hierarchy. Specify maximum time-to-escalate by severity level. Ensure escalation recipients have authority to take action. Track escalation response times and outcomes. Test escalation procedures through tabletop exercises.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without defined escalation criteria, significant AI risks may remain at operational levels without the visibility and authority needed for timely resolution.', 'accountable_transparent', 174);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.4-002', 'MANAGE 1.4', 'Escalation processes include defined triggers for halting AI system operation when risks exceed acceptable levels, with pre-authorized criteria for system owner-initiated shutdowns.', 'Define specific criteria that require immediate AI system shutdown: performance below critical thresholds, confirmed discriminatory outcomes, data breach involving AI training data, confirmed adversarial compromise, and regulatory order. Pre-authorize system owners to halt AI systems meeting shutdown criteria without additional approval. Define restart criteria and approval requirements. Document shutdown and restart events.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without pre-authorized shutdown criteria, decision paralysis during AI crises delays action and extends consumer harm.', 'safe', 175);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.4-003', 'MANAGE 1.4', 'Post-escalation review processes assess whether escalation criteria and processes functioned effectively, incorporating lessons learned into process improvement.', 'Conduct post-escalation reviews for all significant AI risk escalations. Assess: were escalation criteria appropriate and timely? Did the escalation reach the right decision-makers? Were response actions effective? What could be improved? Document lessons learned. Update escalation criteria and processes based on findings. Report escalation effectiveness trends to governance committee.', '{"scaling","full_implementation"}'::TEXT[], 'Unreviewed escalation processes do not improve over time, potentially failing when rapid response is most critical.', 'accountable_transparent', 176);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.1-001', 'MANAGE 2.1', 'The organization implements a structured AI model change management process that evaluates the risk impact of changes before deployment, with approval gates appropriate to the materiality of the change.', 'Define change management for AI systems. Categorize changes by materiality: material changes (new model, significant retraining, new features) require full validation; immaterial changes (parameter tuning, minor fixes) require abbreviated review. Define approval authority by materiality level. Require pre-deployment testing for all changes. Document change rationale, testing results, and approvals. Integrate with enterprise change management.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Uncontrolled AI changes introduce risk without proper assessment, potentially degrading performance, fairness, or stability.', 'accountable_transparent', 177);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.1-002', 'MANAGE 2.1', 'AI change management includes rollback procedures and capabilities, enabling rapid reversion to the previous model version if post-deployment issues are detected.', 'Maintain versioned model artifacts with rollback capability. Test rollback procedures before production deployment. Define rollback triggers: performance below threshold, fairness degradation, operational instability. Implement automated canary deployments with automatic rollback. Ensure rollback can be executed within defined SLAs (e.g., 15 minutes for critical systems). Document rollback procedures and test results.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI deployments without rollback capability force the organization to operate with degraded models while developing fixes, extending harm to consumers.', 'safe', 178);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.1-003', 'MANAGE 2.1', 'Changes to AI systems by third-party vendors are subject to the organization''s change management process, with contractual requirements for advance notification and approval of material changes.', 'Require contractual provisions for vendor AI change management. Mandate advance notification of material model changes. Define what constitutes a material change (new training data, algorithm change, feature change). Require documentation of changes sufficient for the organization''s assessment. Maintain right to reject or delay vendor changes. Monitor vendor change frequency as a risk indicator.', '{"scaling","full_implementation"}'::TEXT[], 'Uncontrolled vendor model changes bypass the organization''s governance process, introducing unassessed risk into production systems.', 'accountable_transparent', 179);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.2-001', 'MANAGE 2.2', 'The organization conducts post-deployment monitoring of AI systems with heightened scrutiny during an initial stabilization period following deployment or material change.', 'Define a heightened monitoring period following AI deployment or material change (e.g., 30-90 days depending on risk tier). During this period: increase monitoring frequency, lower alert thresholds, require daily review of key metrics, and maintain rollback readiness. Define criteria for exiting the heightened monitoring period. Document stabilization monitoring results and transition to steady-state monitoring.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Post-deployment issues not detected during a stabilization period may persist and accumulate impact before steady-state monitoring catches them.', 'valid_reliable', 180);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.2-002', 'MANAGE 2.2', 'Post-deployment monitoring includes A/B testing or champion-challenger comparison where feasible, measuring the new model''s performance against the incumbent in production conditions.', 'Implement champion-challenger frameworks for AI model deployment. Route a percentage of traffic to the new model while maintaining the incumbent. Compare performance across metrics including accuracy, fairness, and business outcomes. Define success criteria for full cutover. Use statistical significance testing before declaring the challenger superior. Document comparison results.', '{"scaling","full_implementation"}'::TEXT[], 'Deploying new models without production comparison risks degrading performance based on offline testing that may not reflect real-world conditions.', 'valid_reliable', 181);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.2-003', 'MANAGE 2.2', 'The organization monitors for unintended consequences of AI deployment, including second-order effects on business processes, customer behavior, and downstream system performance.', 'Expand monitoring beyond direct model metrics to detect unintended consequences. Track: changes in business process outcomes, shifts in customer behavior patterns, performance changes in downstream systems, and unexpected feedback loops. Engage business process owners in identifying potential second-order effects. Investigate anomalies in broader business metrics that correlate with AI deployment timing.', '{"scaling","full_implementation"}'::TEXT[], 'Narrow monitoring focused only on model accuracy misses unintended consequences that may create larger risks than the model itself.', 'safe', 182);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.3-001', 'MANAGE 2.3', 'The organization establishes criteria and processes for AI model retraining, ensuring models remain current while maintaining governance controls over the retraining lifecycle.', 'Define retraining triggers: scheduled (periodic based on risk tier), performance-triggered (monitoring threshold breach), and event-triggered (regime change, data source change). Require validation of retrained models per standard validation process. Implement automated retraining pipelines with governance checkpoints. Monitor for training data quality issues during retraining. Document retraining decisions, methodology, and results.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Ad hoc retraining without defined criteria and governance leads to either stale models or unstable models with insufficient quality assurance.', 'valid_reliable', 183);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.3-002', 'MANAGE 2.3', 'Automated AI retraining pipelines (MLOps) include governance gates that prevent deployment of retrained models that fail performance, fairness, or stability checks.', 'Implement automated governance gates in MLOps pipelines. Required gates: data quality validation, performance threshold check, fairness metric verification, drift comparison, regression testing, and documentation generation. Configure gates to block deployment on failure. Require human approval for override of automated gates. Log all gate results for audit. Ensure pipeline security prevents gate bypass.', '{"scaling","full_implementation"}'::TEXT[], 'Automated retraining without governance gates can deploy degraded or biased models to production without human oversight.', 'valid_reliable', 184);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.3-003', 'MANAGE 2.3', 'The organization maintains comprehensive version control and audit trails for all AI model versions, training data versions, and configuration changes throughout the model lifecycle.', 'Implement versioning for: model code, model artifacts (weights, parameters), training data snapshots, feature engineering pipelines, configuration files, and deployment manifests. Use immutable artifact storage. Maintain audit trails linking model versions to training data, validation results, and deployment decisions. Enable reconstruction of any historical model version. Retain version history per regulatory record-keeping requirements.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without version control and audit trails, the organization cannot reconstruct past model behavior, impeding incident investigation and regulatory response.', 'accountable_transparent', 185);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.4-001', 'MANAGE 2.4', 'The organization establishes AI model decommissioning procedures that ensure safe transition, data preservation for regulatory purposes, and knowledge retention.', 'Define a formal AI decommissioning process. Include: notification to stakeholders, transition to replacement (or manual fallback), data and model archival per retention requirements, documentation of decommissioning rationale, removal from active model inventory, and knowledge transfer to relevant teams. Ensure decommissioned models are inaccessible for production use. Verify dependent systems are updated.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Informal decommissioning risks data loss, orphaned dependencies, regulatory record-keeping violations, and loss of institutional knowledge.', 'accountable_transparent', 186);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.4-002', 'MANAGE 2.4', 'Decommissioning procedures ensure continued ability to explain historical AI decisions for the duration of applicable record-keeping requirements and statute of limitations periods.', 'Preserve sufficient model artifacts and documentation to reconstruct and explain historical AI decisions. Retain: model code, trained artifacts, feature definitions, decision logs, and explanation methodology documentation. Align retention periods with: banking record-keeping requirements (typically 7+ years), fair lending statutes of limitations, and litigation hold obligations. Test archived model reproducibility periodically.', '{"scaling","full_implementation"}'::TEXT[], 'Inability to explain historical AI decisions after decommissioning creates legal and regulatory risk, particularly for fair lending and consumer protection matters.', 'explainable_interpretable', 187);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.4-003', 'MANAGE 2.4', 'The organization conducts post-decommissioning impact assessment to verify that removal of the AI system has not created gaps in business processes, compliance coverage, or customer service.', 'Monitor business operations after AI decommissioning. Verify: replacement processes are functioning correctly, no compliance gaps have emerged, customer service levels are maintained, and no orphaned dependencies exist. Conduct post-decommissioning review within 30 days. Document results and any remediation needed. Report to governance committee if material gaps are identified.', '{"scaling","full_implementation"}'::TEXT[], 'Decommissioning AI without impact verification may create operational gaps that affect customer service or compliance coverage.', 'safe', 188);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-3.1-001', 'MANAGE 3.1', 'The organization integrates AI incident management into its enterprise operational risk framework, with AI-specific incident categories, severity definitions, and response playbooks.', 'Extend the enterprise operational risk incident taxonomy to include AI-specific categories: model failure, bias/discrimination event, adversarial attack, data breach via AI, AI-driven unauthorized action, and AI misinformation. Define severity levels with financial, consumer, and regulatory impact criteria. Develop AI incident playbooks. Train incident response teams on AI-specific scenarios. Conduct AI incident tabletop exercises at least annually.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI incidents that do not fit existing operational risk categories may be misclassified, under-triaged, or handled without appropriate AI expertise.', 'safe', 189);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-3.1-002', 'MANAGE 3.1', 'AI incident response includes defined procedures for identifying and remediating consumer harm, including proactive customer notification and restitution where AI errors have caused financial or access harm.', 'Define consumer harm remediation procedures for AI incidents. Include: rapid assessment of consumer impact scope, proactive notification to affected consumers, restitution calculations and delivery, complaint handling for AI incidents, and regulatory notification where required. Align with CFPB expectations for consumer remediation. Ensure remediation is completed within regulatory timeframes. Document all remediation activities.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Delayed or inadequate consumer remediation after AI incidents increases UDAAP liability and compounds reputational damage.', 'fair_bias_managed', 190);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-3.1-003', 'MANAGE 3.1', 'AI incident data is aggregated and analyzed for trends, root causes, and systemic issues, with findings incorporated into enterprise risk assessments and AI governance improvements.', 'Aggregate AI incident data across the enterprise. Analyze trends: frequency, severity, type, root cause, and affected systems. Identify systemic issues (e.g., common failure modes, recurring data quality problems). Feed incident analysis into: enterprise risk assessments, AI governance framework updates, training programs, and control design improvements. Report incident trends to governance committee quarterly.', '{"scaling","full_implementation"}'::TEXT[], 'Treating AI incidents as isolated events misses systemic patterns that indicate fundamental governance or technical weaknesses.', 'accountable_transparent', 191);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-3.2-001', 'MANAGE 3.2', 'The organization maintains business continuity and disaster recovery plans for critical AI systems, including defined recovery time objectives (RTO) and recovery point objectives (RPO) aligned with enterprise BCM standards.', 'Develop BCP/DR plans for all critical AI systems. Define RTOs and RPOs based on business criticality and regulatory requirements. Implement: model artifact backup and recovery, data pipeline resilience, inference service redundancy, and monitoring failover. Test DR plans annually. Align with enterprise BCM standards. Ensure AI DR plans are reviewed by business continuity management function.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Critical AI systems without BCP/DR plans create operational risk that can cascade to business disruption and customer harm.', 'secure_resilient', 192);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-3.2-002', 'MANAGE 3.2', 'Business continuity plans for AI systems include fallback to non-AI processing capabilities, ensuring that critical business functions can continue operating if AI systems are unavailable.', 'Maintain non-AI fallback capabilities for all critical AI-dependent business processes. Document: manual process procedures, rules-based fallback systems, and degraded mode operations. Train staff on fallback procedures. Test fallback activation regularly. Define triggers for fallback activation. Ensure fallback capabilities can handle production volumes for the defined recovery period.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Organizations that cannot operate without AI have created a single point of failure that threatens business continuity and customer service.', 'secure_resilient', 193);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-3.2-003', 'MANAGE 3.2', 'DR testing for AI systems validates end-to-end recovery, including model serving capability, data pipeline restoration, monitoring reactivation, and integration with downstream systems.', 'Conduct comprehensive AI DR testing at least annually. Test: model artifact restoration and loading, data pipeline recovery, inference service restart, monitoring and alerting reactivation, and downstream system reconnection. Validate end-to-end prediction accuracy post-recovery. Measure actual recovery time against RTO. Document test results and remediate gaps. Include AI systems in enterprise DR exercises.', '{"scaling","full_implementation"}'::TEXT[], 'Untested DR plans for AI systems may fail in actual disasters, leaving critical AI capabilities unrecoverable within required timeframes.', 'secure_resilient', 194);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.1-001', 'MANAGE 4.1', 'The organization maintains a forward-looking AI strategy that anticipates emerging technologies, regulatory changes, and competitive dynamics, with defined processes for strategy review and adaptation.', 'Develop and maintain an AI strategy that addresses: technology evolution (GenAI, agents, multimodal), regulatory trajectory (state AI laws, CFPB guidance, international harmonization), competitive landscape, and talent market dynamics. Review strategy at least semi-annually. Include scenario planning for disruptive changes. Ensure strategy alignment with enterprise strategic plan. Present to board for approval annually.', '{"scaling","full_implementation"}'::TEXT[], 'Reactive AI strategy leaves the organization behind competitors and unprepared for regulatory changes, forcing costly catch-up.', 'accountable_transparent', 195);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.1-002', 'MANAGE 4.1', 'Strategic AI planning includes assessment of evolving regulatory expectations, with proactive positioning to meet anticipated requirements before they become mandatory.', 'Monitor regulatory trajectory through proposed rulemakings, supervisory speeches, enforcement trends, and international developments. Assess potential impact on the AI program. Develop compliance roadmaps for anticipated requirements. Engage with regulators proactively on AI initiatives. Budget for regulatory compliance enhancements. Maintain optionality to adjust if regulatory direction changes.', '{"scaling","full_implementation"}'::TEXT[], 'Financial institutions that wait for final rules to begin compliance preparation face compressed timelines and implementation risk.', 'accountable_transparent', 196);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.1-003', 'MANAGE 4.1', 'The AI strategy includes a responsible AI innovation framework that enables safe experimentation with emerging AI technologies while maintaining governance standards.', 'Establish an AI innovation sandbox with defined guardrails. Allow experimentation with emerging technologies (GenAI, autonomous agents, multimodal AI) under controlled conditions. Define sandbox exit criteria for production promotion. Ensure innovation projects are inventoried and governed. Balance innovation velocity with risk management rigor. Report innovation pipeline to governance committee.', '{"scaling","full_implementation"}'::TEXT[], 'Organizations that either prohibit AI innovation or allow uncontrolled experimentation both suffer — the former from competitive disadvantage, the latter from risk events.', 'safe', 197);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.2-001', 'MANAGE 4.2', 'The organization continuously evaluates its AI governance framework maturity against the FS AI RMF and other applicable frameworks, with defined improvement roadmaps.', 'Conduct annual AI governance maturity self-assessment against the CRI FS AI RMF. Map current state to adoption stages for each control objective. Identify priority gaps based on risk impact. Develop a multi-year improvement roadmap. Track progress against roadmap milestones. Report maturity assessment results to board and governance committee. Engage external assessors for objectivity periodically.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without maturity assessment, the organization cannot systematically close governance gaps or demonstrate progress to regulators.', 'accountable_transparent', 198);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.2-002', 'MANAGE 4.2', 'AI governance improvement initiatives are resourced, tracked, and reported with the same rigor as other enterprise risk management enhancement programs.', 'Treat AI governance improvements as formal projects with: defined scope, budget, timeline, accountable owners, and success criteria. Track progress through enterprise project management processes. Report status to governance committee and board. Ensure adequate funding in annual budgets. Prioritize improvements based on risk impact and regulatory expectations. Celebrate and communicate achievements to reinforce commitment.', '{"scaling","full_implementation"}'::TEXT[], 'AI governance improvements that lack formal tracking and resourcing remain aspirational, with perpetual gaps that draw regulatory criticism.', 'accountable_transparent', 199);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.2-003', 'MANAGE 4.2', 'The organization benchmarks its AI governance practices against peer institutions and industry leaders, identifying areas where it leads, lags, or differs from market practice.', 'Participate in industry benchmarking surveys and studies. Compare AI governance practices across dimensions: organizational structure, policy framework, technical controls, monitoring capabilities, and regulatory readiness. Identify differentiators and gaps. Use benchmarking to calibrate regulatory examination expectations. Share non-proprietary best practices through industry forums. Update improvement roadmap based on benchmarking insights.', '{"full_implementation"}'::TEXT[], 'Without peer benchmarking, the organization cannot calibrate its AI governance investment or anticipate regulatory expectations informed by peer practices.', 'accountable_transparent', 200);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.3-001', 'MANAGE 4.3', 'The organization assesses and manages the workforce implications of AI deployment, including reskilling needs, role evolution, and responsible automation of human tasks.', 'Evaluate workforce impact of AI initiatives. Identify roles affected by AI automation. Develop reskilling and upskilling programs for displaced workers. Design new roles that complement AI capabilities. Implement responsible automation guidelines that consider employee well-being. Communicate transparently with employees about AI''s impact on work. Align with HR policies and labor law requirements.', '{"scaling","full_implementation"}'::TEXT[], 'Poorly managed workforce transitions create operational risk, talent attrition, and reputational damage that undermine AI program success.', 'fair_bias_managed', 201);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.3-002', 'MANAGE 4.3', 'The organization evaluates AI''s impact on financial inclusion objectives and CRA commitments, actively seeking opportunities where AI can expand access to financial services for underserved communities.', 'Assess AI systems for financial inclusion impact. Identify opportunities to use AI to: expand credit access responsibly, reduce costs that enable serving lower-income populations, improve language accessibility, and enhance service to underbanked communities. Align AI inclusion initiatives with CRA strategic plan. Measure and report on financial inclusion outcomes from AI deployment. Partner with community organizations to identify needs.', '{"scaling","full_implementation"}'::TEXT[], 'Financial institutions that deploy AI without considering inclusion may inadvertently widen the digital divide while missing opportunities to serve underbanked populations.', 'fair_bias_managed', 202);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.3-003', 'MANAGE 4.3', 'The organization contributes to industry knowledge-sharing on AI risk management in financial services, supporting the development of standards and best practices that benefit the broader ecosystem.', 'Actively participate in industry AI governance initiatives: CRI working groups, ABA committees, FS-ISAC AI threat sharing, and regulatory roundtables. Contribute to development of industry standards and frameworks. Publish non-proprietary research and case studies. Mentor smaller institutions on AI governance. Engage with academic institutions on financial AI research. Track contributions and report to board.', '{"full_implementation"}'::TEXT[], 'Institutions that only consume industry knowledge without contributing create free-rider effects that weaken the collective AI risk management ecosystem.', 'accountable_transparent', 203);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.1-004', 'GOVERN 1.1', 'The organization maintains documented mapping between each AI system and the specific regulatory requirements it must satisfy, enabling gap analysis and examination readiness.', 'Create and maintain a regulatory requirement mapping for each AI system in the inventory. Map applicable regulations (SR 11-7, ECOA, FCRA, BSA, GLBA, state AI laws) to specific compliance controls. Use the mapping to conduct gap analysis before examinations. Update when regulations change or AI system scope changes. Make mappings available to examiners upon request.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Without AI-to-regulation mapping, the organization cannot efficiently demonstrate compliance during examinations or identify gaps proactively.', 'accountable_transparent', 204);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.4-004', 'GOVERN 1.4', 'The organization evaluates the ethical implications of AI-driven surveillance and monitoring systems used for employee oversight, fraud detection, and customer behavior analysis.', 'Assess ethical dimensions of AI surveillance systems. Evaluate: proportionality of monitoring to risk, employee privacy expectations, potential for chilling effects on legitimate behavior, bias in surveillance targeting, and customer consent. Establish ethical boundaries for AI surveillance. Require ethics review for new monitoring AI deployments. Comply with workplace surveillance laws and ECPA requirements.', '{"scaling","full_implementation"}'::TEXT[], 'Unconstrained AI surveillance damages employee trust, customer relationships, and creates legal liability under workplace and consumer privacy laws.', 'privacy_enhanced', 205);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-1.5-004', 'GOVERN 1.5', 'Technical standards require that all AI models deployed in production undergo peer code review, automated testing, and security scanning before deployment approval.', 'Mandate peer code review for all AI model code before deployment. Implement automated testing suites covering unit tests, integration tests, and performance benchmarks. Require security scanning of AI code and dependencies. Integrate these checks into CI/CD pipelines with deployment blocking on failure. Document review and testing results. Track code review quality metrics.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Deploying AI code without peer review and testing increases the risk of bugs, security vulnerabilities, and operational failures in production.', 'secure_resilient', 206);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-1.4-004', 'MAP 1.4', 'Risk identification for AI used in payments, clearing, and settlement includes assessment of latency risk, throughput limitations, and potential for AI failures to disrupt financial market infrastructure.', 'Conduct specialized risk identification for AI in payment and settlement systems. Assess: maximum latency thresholds before transaction failures, throughput capacity under peak conditions, single-point-of-failure risks, and potential cascading effects on SIFMU counterparties. Include stress scenarios for simultaneous high-volume and model degradation events. Coordinate with treasury and operations risk functions.', '{"scaling","full_implementation"}'::TEXT[], 'AI failures in payment infrastructure can cause cascading settlement failures affecting the broader financial system.', 'safe', 207);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.2-004', 'MAP 3.2', 'The organization implements ongoing bias monitoring for production AI systems, tracking fairness metrics over time and alerting when bias indicators exceed defined thresholds.', 'Deploy continuous fairness monitoring for all consumer-facing AI systems. Calculate fairness metrics on production data at defined intervals (daily for high-risk, weekly for medium). Set alert thresholds for fairness metric degradation. Implement automated reporting of fairness trends. Trigger investigation when alerts fire. Report fairness monitoring results to fair lending compliance. Include in governance committee reporting.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Pre-deployment fairness testing alone is insufficient — bias can emerge or shift over time as populations and data distributions change in production.', 'fair_bias_managed', 208);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.4-004', 'MEASURE 2.4', 'The organization conducts stress testing of AI credit risk models under macroeconomic scenarios aligned with CCAR, DFAST, and internal stress testing programs.', 'Integrate AI credit models into enterprise stress testing. Apply supervisory scenarios (severely adverse, adverse, baseline) to AI model inputs. Measure model performance degradation under stressed conditions. Compare AI model stress results to traditional model results. Assess whether AI models amplify or dampen procyclical effects. Document stress testing methodology and results per CCAR/DFAST requirements.', '{"scaling","full_implementation"}'::TEXT[], 'AI credit models not stress-tested may understate losses under adverse scenarios, potentially leading to insufficient capital reserves.', 'valid_reliable', 209);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.5-004', 'MEASURE 2.5', 'Fairness testing for AI in insurance underwriting evaluates compliance with state insurance regulations, unfair discrimination prohibitions, and rate-filing requirements where AI influences pricing or eligibility.', 'Conduct fairness analysis specific to insurance regulatory requirements. Evaluate AI underwriting and pricing models for unfair discrimination under state insurance laws. Assess compliance with prohibited factor restrictions by state. Ensure AI-influenced rates are supportable in rate filings. Coordinate with insurance compliance and actuarial functions. Document analysis for department of insurance examination.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI in insurance underwriting that produces unfairly discriminatory outcomes violates state insurance laws and risks rate disapproval and enforcement actions.', 'fair_bias_managed', 210);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.6-004', 'MEASURE 2.6', 'The organization provides clear, plain-language explanations of AI-driven decisions to consumers when required by law or regulation, including credit decisions, insurance determinations, and employment actions.', 'Develop consumer-facing explanation capabilities for AI systems subject to disclosure requirements. Generate plain-language explanations that are: specific to the individual decision, accurate regarding the key factors, actionable for the consumer, and compliant with regulatory requirements (ECOA, FCRA, state AI laws). Test consumer comprehension. Maintain explanation logs for audit. Update explanation formats as regulatory guidance evolves.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Failure to provide adequate explanations of AI decisions to consumers violates existing consumer protection laws and emerging AI-specific disclosure requirements.', 'explainable_interpretable', 211);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.7-004', 'MEASURE 2.7', 'The organization implements specific security controls for generative AI systems, including prompt injection defenses, output filtering, and controls preventing unauthorized data access through conversational AI interfaces.', 'Deploy GenAI-specific security controls: input sanitization to prevent prompt injection, output filtering to prevent data leakage and harmful content, session isolation to prevent cross-user data exposure, rate limiting to prevent automated abuse, and access controls ensuring AI only accesses authorized data. Conduct regular red team exercises targeting GenAI systems. Monitor for novel GenAI attack vectors.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Generative AI systems present unique security attack surfaces that traditional application security controls do not adequately address.', 'secure_resilient', 212);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.8-004', 'MEASURE 2.8', 'The organization evaluates AI vendors'' data privacy practices, ensuring third-party AI processing of customer data complies with GLBA safeguards requirements and contractual data handling obligations.', 'Assess vendor AI data privacy practices through due diligence questionnaires and audits. Verify GLBA compliance for all vendors processing NPI in AI systems. Include data handling requirements in vendor contracts. Monitor vendor compliance with contractual data obligations. Assess risk of vendor data aggregation across clients. Implement data minimization principles in vendor AI engagements.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Vendor AI processing of customer data without adequate privacy controls creates GLBA violations and data breach risk for the financial institution.', 'privacy_enhanced', 213);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.1-005', 'MANAGE 1.1', 'The organization develops and maintains contingency plans for AI model failure that include predefined fallback strategies, manual override procedures, and communication templates for stakeholder notification.', 'Create contingency plans for each critical AI system. Include: predefined fallback processing (manual, rules-based, or prior model version), communication templates for customer notification, regulatory notification procedures, business line impact mitigation steps, and restoration criteria. Test contingency plans through simulation exercises. Ensure plans are accessible to operations staff 24/7. Review and update annually.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI system failures without contingency plans result in prolonged service disruptions, ad hoc responses, and delayed stakeholder communication.', 'secure_resilient', 214);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.1-004', 'MANAGE 2.1', 'The organization tracks and manages technical debt in AI systems, preventing accumulation of shortcuts and deferred improvements that increase long-term risk.', 'Inventory and track AI technical debt: outdated dependencies, deprecated features, deferred refactoring, missing tests, and documentation gaps. Assess risk impact of accumulated technical debt. Allocate dedicated capacity for technical debt reduction (e.g., 20% of AI engineering capacity). Prioritize debt remediation based on risk and cost of delay. Report technical debt levels to governance committee. Prevent critical debt accumulation.', '{"scaling","full_implementation"}'::TEXT[], 'AI technical debt silently increases fragility and operational risk, eventually leading to costly failures or forced rewrites.', 'secure_resilient', 215);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-3.1-004', 'MANAGE 3.1', 'The organization maintains a register of AI-related operational losses and near-misses, integrating AI events into the enterprise operational risk loss database for comprehensive risk assessment.', 'Record AI-related operational losses in the enterprise loss database. Capture: direct financial losses, remediation costs, regulatory fines, and opportunity costs. Track near-misses that could have resulted in losses. Categorize by AI risk type for trend analysis. Use loss data to calibrate AI risk models and capital assessments. Report to operational risk committee and board. Benchmark loss experience against industry data.', '{"scaling","full_implementation"}'::TEXT[], 'AI operational losses not captured in the enterprise loss database distort the organization''s understanding of total operational risk exposure.', 'accountable_transparent', 216);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-2.1-004', 'GOVERN 2.1', 'The organization ensures clear separation of duties between AI system development, validation, and deployment approval functions, preventing conflicts of interest in AI governance.', 'Enforce separation of duties: developers cannot validate their own models, model owners cannot approve deployment without independent sign-off, and validation findings cannot be overridden by development leadership. Document organizational structure supporting separation of duties. Verify separation is maintained for third-party AI through contractual and oversight mechanisms. Audit separation of duties compliance annually.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'Conflicted AI governance where developers self-approve systems undermines independent oversight and is a fundamental SR 11-7 deficiency.', 'accountable_transparent', 217);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-3.1-004', 'GOVERN 3.1', 'The organization identifies and manages concentration risk in AI, including dependency on single AI platforms, shared model architectures, or common training datasets across multiple AI systems.', 'Assess AI concentration risk across: technology platforms (single cloud provider), model architectures (all systems using one approach), data sources (common training data across models), and vendor concentration. Quantify the potential impact of concentrated failures. Develop diversification strategies for critical concentrations. Implement monitoring for concentration risk indicators. Report concentration risk to governance committee.', '{"scaling","full_implementation"}'::TEXT[], 'AI concentration creates correlated failure risk that could simultaneously affect multiple business functions.', 'secure_resilient', 218);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-2.1-004', 'MAP 2.1', 'The organization documents assumptions about the operating environment that underpin AI system design, and monitors for changes in these assumptions that could invalidate model performance.', 'Catalog key assumptions for each AI system: data distribution stability, regulatory environment, market conditions, customer behavior patterns, and technology infrastructure. Define monitoring approaches for each assumption. Set triggers for assumption review when operating environment changes materially. Link assumption violations to model revalidation triggers. Document assumption monitoring in ongoing monitoring plans.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems designed under assumptions that no longer hold produce unreliable outputs, but this degradation is invisible without explicit assumption monitoring.', 'valid_reliable', 219);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.10-004', 'MEASURE 2.10', 'The organization measures and manages the cost efficiency of AI operations, tracking inference costs, infrastructure utilization, and return on AI investment across the portfolio.', 'Track AI operational costs at system level: compute costs, data storage, API calls, infrastructure maintenance, and human oversight costs. Calculate cost per prediction/inference. Monitor cost trends and anomalies. Compare costs to business value delivered. Optimize: right-size infrastructure, implement model efficiency improvements, and consolidate redundant capabilities. Report AI cost efficiency metrics to finance and governance committee.', '{"scaling","full_implementation"}'::TEXT[], 'Unmanaged AI operational costs can erode the business case for AI investments and divert resources from higher-value initiatives.', 'accountable_transparent', 220);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.2-004', 'MANAGE 2.2', 'Post-deployment monitoring for AI in BSA/AML transaction monitoring includes assessment of suspicious activity detection rates, false positive rates, and investigation efficiency impacts.', 'Monitor BSA/AML AI performance metrics: SAR filing rates, true positive rates, false positive rates, investigation time savings, and typology coverage. Compare AI-augmented detection to historical rules-based detection. Track regulatory feedback on AI-influenced SARs. Monitor for changes in transaction patterns that may indicate model drift. Report BSA/AML AI performance to BSA Officer and governance committee.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'BSA/AML AI that degrades detection capability without monitoring may result in BSA compliance failures and FinCEN enforcement actions.', 'valid_reliable', 221);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.11-004', 'MEASURE 2.11', 'The organization assesses AI-human handoff processes in customer service contexts, measuring whether transitions between AI and human agents are seamless and do not degrade customer experience.', 'Measure AI-human handoff quality: customer wait time during transfer, context preservation (does the human agent have AI interaction history), customer satisfaction with the transition, resolution rate post-handoff, and abandonment rate during handoff. Optimize handoff triggers to balance AI efficiency with customer needs. Test handoff processes regularly. Collect and analyze customer feedback on AI-human transitions.', '{"scaling","full_implementation"}'::TEXT[], 'Poor AI-human handoffs frustrate customers, increase call handling time, and erode trust in the institution''s service quality.', 'valid_reliable', 222);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-4.1-004', 'GOVERN 4.1', 'The organization establishes shared infrastructure and platforms for AI development and deployment that promote consistency, efficiency, and governance compliance across AI teams.', 'Invest in centralized AI platforms providing: standardized development environments, shared feature stores, model registry, automated MLOps pipelines, and monitoring infrastructure. Embed governance controls into the platform (automated validation checks, documentation requirements, approval workflows). Enable self-service AI development within guardrails. Track platform adoption and governance compliance metrics.', '{"scaling","full_implementation"}'::TEXT[], 'Fragmented AI infrastructure leads to inconsistent practices, duplicated effort, and difficulty enforcing governance standards across teams.', 'accountable_transparent', 223);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('GV-5.2-004', 'GOVERN 5.2', 'The organization ensures AI-driven customer communications and disclosures are accurate, not misleading, and compliant with UDAAP, Truth in Lending, and other consumer protection requirements.', 'Review all AI-generated customer communications for accuracy and compliance before deployment. Test generative AI outputs against UDAAP standards (not unfair, deceptive, or abusive). Verify compliance with TILA, Reg Z, and other disclosure requirements for AI-generated financial content. Implement output validation and filtering for compliance-sensitive communications. Monitor production outputs for compliance drift.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI-generated communications that are inaccurate or misleading violate consumer protection laws and create UDAAP enforcement risk.', 'accountable_transparent', 224);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MP-3.3-004', 'MAP 3.3', 'The organization implements data loss prevention controls for AI systems that prevent unauthorized transfer or exposure of sensitive training data, model parameters, and inference results.', 'Implement DLP controls tailored to AI data flows. Monitor for unauthorized data transfers of: training datasets, model weights and parameters, customer inference results, and feature store data. Apply network-level DLP for AI development and serving environments. Control data egress from AI systems. Prevent unauthorized copying of model artifacts. Integrate AI DLP with enterprise DLP program.', '{"minimum_viable","scaling","full_implementation"}'::TEXT[], 'AI systems without DLP controls risk unauthorized data exposure, model theft, and regulatory violations for data handling failures.', 'privacy_enhanced', 225);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-1.3-004', 'MANAGE 1.3', 'AI risk communication strategies address the specific needs of regulatory examination teams, with pre-prepared materials that clearly explain AI systems, governance processes, and risk management practices.', 'Develop examination readiness packages for AI systems. Include: AI inventory overviews, governance framework summaries, model documentation indexes, validation report summaries, monitoring dashboards, and issue status reports. Assign designated examination liaisons with AI expertise. Conduct pre-examination readiness drills. Maintain materials in up-to-date, regulator-accessible format. Brief examination teams proactively on AI program developments.', '{"scaling","full_implementation"}'::TEXT[], 'Poorly prepared examination responses for AI create unfavorable impressions with regulators and extend examination timelines with follow-up requests.', 'accountable_transparent', 226);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-4.1-004', 'MANAGE 4.1', 'The organization''s AI strategy addresses the unique risks and opportunities of agentic AI systems — AI that can take autonomous actions, use tools, and chain multi-step reasoning — with enhanced governance for autonomous decision-making.', 'Develop governance frameworks for agentic AI that address: scope of permitted autonomous actions, guardrails and boundaries, monitoring of autonomous behavior chains, approval requirements for tool use and external system access, and human oversight escalation triggers. Assess agentic AI risks including: unintended action chains, cascading errors, and unauthorized scope expansion. Define deployment criteria specific to agentic systems.', '{"full_implementation"}'::TEXT[], 'Agentic AI systems that take autonomous actions without adequate governance can cause cascading harm that is difficult to detect and reverse.', 'safe', 227);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-3.2-004', 'MEASURE 3.2', 'AI risk reporting to the board includes clear articulation of the AI risk-return trade-off, enabling informed board decisions about the pace and scope of AI adoption.', 'Frame board AI reporting in risk-return terms the board can act on. Present: AI business value delivered against risk costs, risk trend direction (improving/stable/deteriorating), regulatory readiness assessment, and key decisions requiring board input. Provide comparative context (industry trends, peer benchmarks). Avoid excessive technical jargon. Include forward-looking risk projections. Enable the board to make informed decisions on AI strategy and appetite.', '{"scaling","full_implementation"}'::TEXT[], 'Board reporting that is either too technical or too abstract fails to support informed governance, resulting in either uninformed approval or excessive caution.', 'accountable_transparent', 228);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MS-2.9-004', 'MEASURE 2.9', 'The organization assesses AI''s impact on operational resilience, evaluating whether AI adoption increases or decreases the institution''s ability to absorb and recover from operational disruptions.', 'Evaluate AI''s net effect on operational resilience. Assess: does AI create new single points of failure? Does AI improve processing flexibility? Can AI-dependent processes recover from disruptions? Is AI infrastructure diversified across failure domains? Include AI in operational resilience scenario testing per regulatory expectations. Document AI resilience assessment in operational resilience framework.', '{"scaling","full_implementation"}'::TEXT[], 'AI that improves efficiency but reduces resilience creates hidden fragility that manifests during operational stress events.', 'secure_resilient', 229);
INSERT INTO sentinel_control_objectives (id, subcategory_id, objective_text, implementation_guidance, adoption_stages, risk_statement, trustworthy_principle, sort_order) VALUES ('MG-2.3-004', 'MANAGE 2.3', 'The organization establishes model performance benchmarks that are updated with each retraining cycle, enabling longitudinal tracking of model effectiveness and early detection of secular performance trends.', 'Maintain historical performance benchmarks for each model across retraining cycles. Track key metrics over time to identify secular trends (gradual improvement or degradation). Compare each retrained model to: initial deployment performance, previous version, and peer models for similar use cases. Use longitudinal data to inform retraining frequency decisions. Alert when performance trends indicate approaching risk thresholds.', '{"scaling","full_implementation"}'::TEXT[], 'Without longitudinal benchmarks, organizations cannot distinguish between normal variation and concerning performance trends that warrant intervention.', 'valid_reliable', 230);
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('AI Risk Management Framework', 'A voluntary framework published by NIST (AI 100-1) that provides organizations with a structured approach to managing risks associated with AI systems throughout their lifecycle. It is organized around four core functions: Govern, Map, Measure, and Manage.', 'NIST AI RMF', '{"Trustworthiness","AI system","AI lifecycle","Risk assessment"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('AI system', 'An engineered or machine-based system that can, for a given set of objectives, generate outputs such as predictions, recommendations, decisions, or content that influence real or virtual environments. AI systems vary in autonomy and adaptiveness after deployment.', 'NIST AI RMF', '{"AI lifecycle","AI actor","Machine learning"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('AI actor', 'Any individual or organization that plays a role in the design, development, deployment, evaluation, use, or monitoring of an AI system. AI actors span the full AI lifecycle and include developers, deployers, operators, evaluators, affected individuals, and oversight bodies.', 'NIST AI RMF', '{"AI system","AI lifecycle","Human oversight"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('AI lifecycle', 'The sequential and iterative stages through which an AI system progresses, including planning and design, data collection and processing, model building, testing, deployment, operation, monitoring, and eventual decommissioning.', 'NIST AI RMF', '{"AI system","AI actor","Decommissioning","TEVV"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Trustworthiness', 'A composite quality of AI systems encompassing characteristics such as validity, reliability, safety, security, resilience, accountability, transparency, explainability, interpretability, privacy, and fairness. The NIST AI RMF treats trustworthiness as the overarching goal of AI risk management.', 'NIST AI RMF', '{"Fairness","Transparency","Accountability","Safety","Reliability"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Bias (harmful)', 'Systematic errors in AI system outputs that create unfair outcomes for particular groups or individuals. Harmful bias can originate from training data, algorithm design, or deployment context, and may be statistical, cognitive, or systemic in nature.', 'NIST AI RMF', '{"Fairness","Trustworthiness","Data governance"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Fairness', 'The principle that AI systems should not produce unjust or prejudicial outcomes for different demographic groups or individuals. Fairness encompasses equitable treatment, equalized opportunity, and the mitigation of harmful bias throughout the AI lifecycle.', 'NIST AI RMF', '{"Bias (harmful)","Trustworthiness","Accountability"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Transparency', 'The extent to which information about an AI system and its outputs is available to individuals interacting with it or affected by it. Transparency supports accountability and helps stakeholders understand how decisions are made.', 'NIST AI RMF', '{"Explainability","Interpretability","Accountability","Audit trail"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Accountability', 'The principle that organizations and individuals responsible for AI systems are answerable for their functioning, outcomes, and compliance with applicable norms. Accountability requires clear roles, governance structures, and mechanisms for redress.', 'NIST AI RMF', '{"Transparency","Human oversight","Three lines of defense","Governance"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Explainability', 'The ability to articulate the reasons behind an AI system''s outputs or decisions in terms understandable to relevant stakeholders. Explainability is distinct from interpretability in that it focuses on post-hoc justification rather than inherent model transparency.', 'NIST AI RMF', '{"Interpretability","Transparency","Trustworthiness"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Interpretability', 'The degree to which a human can understand the internal mechanisms and decision-making processes of an AI model without supplementary explanation. Interpretable models allow stakeholders to directly inspect how inputs map to outputs.', 'NIST AI RMF', '{"Explainability","Transparency","Neural network"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Privacy', 'The norms and practices that protect individuals'' personal information and autonomy from unauthorized collection, use, or disclosure by AI systems. Privacy in AI encompasses data minimization, consent, anonymization, and compliance with applicable data protection laws.', 'NIST AI RMF', '{"Data governance","Security","Trustworthiness"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Security', 'The protection of AI systems, their data, and infrastructure from unauthorized access, manipulation, or disruption. AI security addresses threats such as adversarial attacks, data poisoning, model theft, and prompt injection.', 'NIST AI RMF', '{"Resilience","Privacy","Red teaming","Guardrails"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Resilience', 'The capacity of an AI system to withstand, recover from, and adapt to unexpected conditions, adversarial attacks, or operational disruptions while maintaining acceptable performance levels.', 'NIST AI RMF', '{"Security","Reliability","Safety","Incident response"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Validity', 'The extent to which an AI system''s outputs accurately represent what they are intended to measure or predict, as confirmed through empirical testing against ground truth or domain requirements.', 'NIST AI RMF', '{"Reliability","TEVV","Back-testing","Model validation"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Reliability', 'The ability of an AI system to perform its intended functions consistently and accurately over time, across different conditions, and within defined operating parameters.', 'NIST AI RMF', '{"Validity","Safety","Model decay","Concept drift"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Safety', 'The condition in which an AI system does not, under defined conditions, lead to a state that endangers human life, health, property, or the environment. Safety requirements increase with the criticality and autonomy of the AI application.', 'NIST AI RMF', '{"Resilience","Reliability","Human oversight","Guardrails"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Risk tolerance', 'The level and type of risk an organization is willing to accept in pursuit of its objectives. Risk tolerance defines the boundaries within which AI systems may operate and informs decisions about risk treatment.', 'NIST AI RMF', '{"Risk appetite","Risk assessment","Risk treatment","Material risk"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Risk assessment', 'The systematic process of identifying, analyzing, and evaluating risks associated with an AI system, including the likelihood and severity of potential negative impacts across technical, societal, and organizational dimensions.', 'NIST AI RMF', '{"Risk tolerance","Risk treatment","Residual risk","Scenario analysis"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Risk treatment', 'The process of selecting and implementing measures to modify identified AI risks, including risk avoidance, mitigation, transfer, or acceptance. Treatment decisions are informed by risk assessment outcomes and organizational risk tolerance.', 'NIST AI RMF', '{"Risk assessment","Risk tolerance","Residual risk","Control objective"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Residual risk', 'The risk that remains after risk treatment measures have been applied. Residual risk must be documented, monitored, and accepted within the organization''s risk tolerance, as no treatment can eliminate all risk.', 'NIST AI RMF', '{"Risk treatment","Risk tolerance","Risk assessment"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('TEVV', 'Testing, Evaluation, Validation, and Verification. A comprehensive set of processes used throughout the AI lifecycle to confirm that an AI system meets its requirements, performs as intended, and produces trustworthy outputs under various conditions.', 'NIST AI RMF', '{"Model validation","Back-testing","Red teaming","Benchmarking"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Model risk', 'The potential for adverse consequences arising from decisions based on incorrect or misused model outputs. In financial services, model risk is a supervisory concern governed by guidance such as SR 11-7 and OCC 2011-12.', 'SR 11-7 / OCC 2011-12', '{"Model validation","Model Risk Management","SR 11-7","Model decay"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Model validation', 'The independent assessment of a model''s conceptual soundness, implementation correctness, and ongoing performance to ensure it is fit for its intended purpose. Validation is a core component of model risk management in financial services.', 'SR 11-7 / OCC 2011-12', '{"Model risk","TEVV","Effective challenge","Back-testing"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Third-party risk', 'The risks introduced when an organization relies on external vendors, partners, or service providers for AI system components, data, or services. Third-party risk management requires due diligence, contractual controls, and ongoing monitoring.', 'NIST AI RMF', '{"Supply chain risk","Operational risk","AI actor"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Supply chain risk', 'Risks arising from the components, data, models, and services sourced from third parties that are integrated into an AI system. Supply chain risks include data provenance issues, model vulnerabilities, and dependency on external infrastructure.', 'NIST AI RMF', '{"Third-party risk","Data lineage","Data governance"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Human oversight', 'The involvement of humans in monitoring, supervising, and intervening in AI system operations to ensure safe, ethical, and effective outcomes. Oversight can range from human-in-the-loop (approval before action) to human-on-the-loop (monitoring with intervention capability).', 'NIST AI RMF', '{"Human-AI teaming","Accountability","Safety","Agentic AI"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Human-AI teaming', 'The collaborative interaction between humans and AI systems where each contributes complementary capabilities to achieve outcomes neither could accomplish as effectively alone. Effective teaming requires calibrated trust, clear role delineation, and appropriate human oversight.', 'NIST AI RMF', '{"Human oversight","AI actor","Trustworthiness"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Decommissioning', 'The planned and controlled retirement of an AI system, including the cessation of its operations, archival or deletion of associated data and models, and documentation of its operational history. Decommissioning is a critical but often overlooked phase of the AI lifecycle.', 'NIST AI RMF', '{"AI lifecycle","Data governance","Audit trail"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Incident response', 'The processes and procedures for detecting, reporting, analyzing, and remediating adverse events or failures involving AI systems. Incident response plans should be pre-established, tested, and integrated with existing organizational response frameworks.', 'NIST AI RMF', '{"Resilience","Safety","Operational risk","Red teaming"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Red teaming', 'A structured adversarial testing approach where a designated team probes an AI system for vulnerabilities, failure modes, and unintended behaviors by simulating realistic attack scenarios. Red teaming is a key TEVV activity for identifying risks that standard testing may miss.', 'NIST AI RMF', '{"TEVV","Security","Stress testing","Guardrails"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Adoption stage', 'In the FS AI RMF, one of three maturity levels (Early, Expanding, Mature) that characterizes an organization''s current state of AI adoption. The applicable adoption stage determines which control objectives are relevant and the expected rigor of implementation.', 'FS AI RMF', '{"Control objective","Maturity model","AI Risk Management Framework"}'::TEXT[], 'regulatory');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Control objective', 'A specific, measurable goal that an organization should achieve to manage a particular AI risk. The FS AI RMF defines 230 control objectives organized by the NIST AI RMF functions (Govern, Map, Measure, Manage) and mapped to adoption stages.', 'FS AI RMF', '{"Adoption stage","Crosswalk","AI Risk Management Framework"}'::TEXT[], 'regulatory');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Crosswalk', 'A mapping between the requirements, controls, or standards of two or more regulatory frameworks, enabling organizations to demonstrate compliance across multiple regimes simultaneously. Crosswalks identify overlaps, gaps, and equivalences between frameworks.', 'FS AI RMF', '{"Control objective","Informative reference","SR 11-7"}'::TEXT[], 'regulatory');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Informative reference', 'A supplementary document, standard, or guidance that provides additional context, detail, or implementation advice for a control objective or framework element. Informative references are not mandatory but help organizations operationalize requirements.', 'NIST AI RMF', '{"Control objective","Crosswalk","AI Risk Management Framework"}'::TEXT[], 'regulatory');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Maturity model', 'A structured framework for assessing an organization''s capability and sophistication in a specific domain, typically defined as a progression through discrete levels. In AI risk management, maturity models help organizations benchmark their current state and plan improvements.', 'Domain Knowledge', '{"Adoption stage","Control objective","AI Risk Management Framework"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('SIFMU', 'Systemically Important Financial Market Utility. A financial market infrastructure designated by the Financial Stability Oversight Council (FSOC) whose failure could pose systemic risk to the US financial system. SIFMUs face heightened supervisory expectations for risk management, including AI risk.', 'Dodd-Frank Act / Domain Knowledge', '{"Operational risk","Concentration risk","OCC"}'::TEXT[], 'regulatory');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('SR 11-7', 'Federal Reserve Supervisory Guidance on Model Risk Management, issued in 2011. SR 11-7 establishes expectations for model development, validation, and governance at banking organizations and remains the foundational regulatory reference for model risk management in US financial services.', 'Federal Reserve', '{"Model risk","Model Risk Management","Model validation","OCC","Effective challenge"}'::TEXT[], 'regulatory');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('OCC', 'Office of the Comptroller of the Currency. An independent bureau of the US Treasury Department that charters, regulates, and supervises national banks and federal savings associations. The OCC has issued parallel model risk guidance (OCC 2011-12) and is actively engaged in AI risk policy.', 'Domain Knowledge', '{"SR 11-7","Model Risk Management","Regulatory capital"}'::TEXT[], 'regulatory');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Model Risk Management', 'The organizational framework of policies, processes, and controls for identifying, measuring, monitoring, and controlling model risk across the enterprise. In financial services, MRM programs are required by SR 11-7 and OCC 2011-12 and are increasingly expected to cover AI/ML models.', 'SR 11-7 / OCC 2011-12', '{"Model risk","Model validation","SR 11-7","Three lines of defense"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Three lines of defense', 'A governance model in which the first line (business/operations) owns and manages risk, the second line (risk management and compliance) provides independent oversight and challenge, and the third line (internal audit) provides independent assurance. This model is foundational to financial services risk governance.', 'Domain Knowledge', '{"Effective challenge","Accountability","Model Risk Management"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Effective challenge', 'Critical analysis and questioning of a model''s design, assumptions, outputs, and limitations by qualified individuals who are independent of the model development process. Effective challenge is a core requirement of SR 11-7 and ensures that model risk is surfaced and addressed.', 'SR 11-7', '{"Model validation","Three lines of defense","Model Risk Management"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Risk appetite', 'The aggregate amount and types of risk an organization is willing to accept or pursue in order to achieve its strategic objectives, expressed as a board-approved statement. Risk appetite is broader than risk tolerance and sets the tone for enterprise risk management.', 'Domain Knowledge', '{"Risk tolerance","Risk capacity","Risk assessment","Material risk"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Risk capacity', 'The maximum level of risk an organization can absorb before it threatens its viability, as determined by its capital, liquidity, operational capability, and regulatory constraints. Risk capacity sets the outer boundary within which risk appetite must be defined.', 'Domain Knowledge', '{"Risk appetite","Risk tolerance","Regulatory capital"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Concentration risk', 'The risk arising from overexposure to a single counterparty, sector, geography, technology, or data source. In AI, concentration risk can manifest as dependence on a single model vendor, a single training dataset, or a dominant foundation model provider.', 'Domain Knowledge', '{"Third-party risk","Operational risk","Supply chain risk"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Operational risk', 'The risk of loss resulting from inadequate or failed internal processes, people, systems, or external events. AI-specific operational risks include model failures, data pipeline disruptions, and unintended autonomous actions.', 'Domain Knowledge', '{"Incident response","Resilience","Compliance risk","Model risk"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Compliance risk', 'The risk of legal or regulatory sanctions, financial loss, or reputational damage arising from failure to comply with applicable laws, regulations, or standards. AI introduces novel compliance risks related to algorithmic fairness, data privacy, and emerging AI-specific regulations.', 'Domain Knowledge', '{"Regulatory capital","OCC","SR 11-7","Accountability"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Regulatory capital', 'The minimum amount of capital a financial institution must hold as required by banking regulators to absorb losses and maintain solvency. AI model failures in areas like credit risk or market risk can directly impact regulatory capital calculations.', 'Domain Knowledge', '{"OCC","Compliance risk","Risk capacity","Stress testing"}'::TEXT[], 'regulatory');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Stress testing', 'A risk analysis technique that evaluates how a system, model, or portfolio performs under extreme but plausible adverse scenarios. For AI systems, stress testing includes evaluating model behavior under distribution shifts, adversarial inputs, and degraded data quality.', 'Domain Knowledge', '{"Scenario analysis","Red teaming","Model validation","Back-testing"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Scenario analysis', 'A forward-looking risk assessment method that explores the potential impacts of hypothetical events or conditions on an organization or system. Scenario analysis for AI includes evaluating the effects of model failures, data breaches, or regulatory changes.', 'Domain Knowledge', '{"Stress testing","Risk assessment","Resilience"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Material risk', 'A risk of sufficient magnitude that its realization could significantly affect an organization''s financial condition, operations, or reputation. Materiality thresholds determine which AI systems require enhanced governance, validation, and oversight.', 'Domain Knowledge', '{"Risk appetite","Risk tolerance","Model risk"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Audit trail', 'A chronological record of system activities, decisions, and changes that enables reconstruction and review of the sequence of events. For AI systems, audit trails should capture data inputs, model versions, configuration changes, predictions, and human interventions.', 'Domain Knowledge', '{"Transparency","Accountability","Data lineage","Data governance"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Data governance', 'The framework of policies, standards, processes, and organizational structures that ensure data is managed as a strategic asset with appropriate quality, security, privacy, and compliance controls throughout its lifecycle.', 'Domain Knowledge', '{"Data lineage","Privacy","Audit trail","Bias (harmful)"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Data lineage', 'The documented history of data as it flows through collection, transformation, storage, and consumption stages. Data lineage enables organizations to trace AI model inputs back to their origins for auditability, debugging, and regulatory compliance.', 'Domain Knowledge', '{"Data governance","Audit trail","Feature engineering","Supply chain risk"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Feature engineering', 'The process of selecting, transforming, and creating input variables (features) from raw data to improve the performance and interpretability of machine learning models. Feature engineering decisions can introduce or mitigate bias and significantly affect model behavior.', 'Domain Knowledge', '{"Data lineage","Machine learning","Bias (harmful)","Data governance"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Concept drift', 'A change in the statistical relationship between input features and the target variable over time, causing a model''s learned patterns to become outdated. Concept drift degrades model performance and requires ongoing monitoring and retraining strategies.', 'Domain Knowledge', '{"Data drift","Model decay","Reliability","TEVV"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Data drift', 'A change in the statistical distribution of input data over time compared to the data on which a model was trained. Data drift can degrade model accuracy even when the underlying relationship between features and target remains stable.', 'Domain Knowledge', '{"Concept drift","Model decay","Model validation"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Model decay', 'The gradual degradation of a model''s predictive performance over time, typically caused by concept drift, data drift, or changes in the operating environment. Model decay necessitates ongoing monitoring, retraining, and validation protocols.', 'Domain Knowledge', '{"Concept drift","Data drift","Model validation","Champion-challenger"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Champion-challenger', 'A model management strategy in which the currently deployed model (champion) is continuously compared against one or more alternative models (challengers) to determine whether a replacement would improve performance. This approach supports evidence-based model updates.', 'Domain Knowledge', '{"Shadow model","Model decay","Model validation","Benchmarking"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Shadow model', 'A model that runs in parallel with the production model, receiving the same inputs and generating predictions, but whose outputs are not used for decision-making. Shadow models are used to evaluate candidate replacements under real-world conditions without production risk.', 'Domain Knowledge', '{"Champion-challenger","Model validation","Back-testing"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Back-testing', 'A validation technique that evaluates a model''s predictions against actual observed outcomes using historical data. Back-testing assesses whether a model would have performed acceptably in the past and is a standard requirement in financial model validation.', 'Domain Knowledge', '{"Model validation","TEVV","Benchmarking","Stress testing"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Benchmarking', 'The practice of comparing an AI model''s performance against established standards, baseline models, or industry peers using standardized metrics and test datasets. Benchmarking provides objective context for evaluating model quality and identifying areas for improvement.', 'Domain Knowledge', '{"Back-testing","TEVV","Champion-challenger","Model validation"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Machine learning', 'A subset of artificial intelligence in which algorithms learn patterns from data to make predictions or decisions without being explicitly programmed for each task. Machine learning encompasses supervised, unsupervised, and reinforcement learning paradigms.', 'Domain Knowledge', '{"Deep learning","Supervised learning","Unsupervised learning","Reinforcement learning"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Deep learning', 'A subset of machine learning that uses neural networks with multiple layers (deep architectures) to learn hierarchical representations of data. Deep learning has achieved state-of-the-art results in vision, language, and other domains but typically has lower interpretability.', 'Domain Knowledge', '{"Neural network","Machine learning","Large language model","Interpretability"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Neural network', 'A computational model inspired by biological neural systems, consisting of interconnected layers of nodes (neurons) that process and transform inputs through learned weights and activation functions. Neural networks are the foundation of deep learning systems.', 'Domain Knowledge', '{"Deep learning","Machine learning","Interpretability"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Large language model', 'A neural network trained on massive text corpora to understand and generate human language, typically using transformer architectures with billions of parameters. LLMs power conversational AI, text generation, and many generative AI applications but introduce unique risks including hallucination and prompt injection.', 'Domain Knowledge', '{"Generative AI","Hallucination","Prompt engineering","Alignment"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Generative AI', 'AI systems capable of creating new content such as text, images, audio, code, or synthetic data based on patterns learned from training data. Generative AI introduces novel risks around authenticity, intellectual property, and the propagation of misinformation.', 'NIST AI 600-1', '{"Large language model","Hallucination","Alignment","Guardrails"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Reinforcement learning', 'A machine learning paradigm in which an agent learns to make decisions by taking actions in an environment and receiving reward or penalty signals. Reinforcement learning is used in robotics, game playing, and increasingly in fine-tuning language models via RLHF.', 'Domain Knowledge', '{"Machine learning","Alignment","Agentic AI"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Supervised learning', 'A machine learning approach in which a model is trained on labeled data, learning to map inputs to known outputs. Common applications include classification, regression, and structured prediction tasks.', 'Domain Knowledge', '{"Machine learning","Unsupervised learning","Feature engineering"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Unsupervised learning', 'A machine learning approach in which a model identifies patterns, structures, or groupings in unlabeled data without explicit target variables. Applications include clustering, anomaly detection, and dimensionality reduction.', 'Domain Knowledge', '{"Machine learning","Supervised learning","Embeddings"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Transfer learning', 'A machine learning technique in which a model trained on one task or dataset is adapted for a different but related task, leveraging previously learned representations to improve performance and reduce training data requirements.', 'Domain Knowledge', '{"Fine-tuning","Large language model","Deep learning"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Fine-tuning', 'The process of further training a pre-trained model on a smaller, task-specific dataset to adapt its behavior for a particular use case. Fine-tuning is a key step in deploying foundation models for domain-specific applications in financial services and other regulated industries.', 'Domain Knowledge', '{"Transfer learning","Large language model","Alignment"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Prompt engineering', 'The practice of designing, structuring, and optimizing input prompts to elicit desired outputs from large language models. Effective prompt engineering can improve accuracy, reduce hallucination, and enforce output constraints without model retraining.', 'Domain Knowledge', '{"Large language model","Hallucination","Guardrails","Generative AI"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Embeddings', 'Dense, low-dimensional vector representations of data (text, images, etc.) that capture semantic relationships and enable similarity computations. Embeddings are foundational to modern AI systems for search, recommendation, clustering, and retrieval-augmented generation.', 'Domain Knowledge', '{"Neural network","Large language model","Unsupervised learning"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Hallucination', 'The generation of outputs by an AI system that are syntactically plausible but factually incorrect, unsupported, or fabricated. Hallucination is a significant risk in generative AI and large language models, particularly in regulated domains where accuracy is critical.', 'NIST AI 600-1', '{"Large language model","Generative AI","Reliability","Guardrails"}'::TEXT[], 'risk');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Alignment', 'The degree to which an AI system''s objectives, behaviors, and outputs are consistent with human values, intentions, and established norms. Alignment research addresses how to ensure AI systems act in accordance with their intended purpose and do not pursue unintended goals.', 'Domain Knowledge', '{"Guardrails","Safety","Trustworthiness","Reinforcement learning"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Guardrails', 'Technical and procedural safeguards that constrain AI system behavior within acceptable boundaries, preventing harmful, off-topic, or policy-violating outputs. Guardrails include input filtering, output validation, content policies, and automated monitoring.', 'Domain Knowledge', '{"Alignment","Safety","Security","Hallucination"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Agentic AI', 'AI systems that can autonomously plan, reason, use tools, and take multi-step actions to achieve goals with minimal human intervention. Agentic AI introduces heightened risks around controllability, accountability, and unintended consequences that require robust human oversight frameworks.', 'NIST AI 600-1', '{"Human oversight","Alignment","Safety","Large language model"}'::TEXT[], 'technical');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Govern', 'The first core function of the NIST AI RMF, focused on cultivating a culture of risk management, establishing policies and processes, defining roles and responsibilities, and ensuring organizational accountability for AI risk management across the enterprise.', 'NIST AI RMF', '{"Map","Measure","Manage","AI Risk Management Framework","Accountability"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Map', 'The second core function of the NIST AI RMF, focused on establishing the context for AI risk management by identifying and documenting the AI system''s purpose, stakeholders, potential impacts, constraints, and the broader operational environment.', 'NIST AI RMF', '{"Govern","Measure","Manage","AI Risk Management Framework","Risk assessment"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Measure', 'The third core function of the NIST AI RMF, focused on employing quantitative and qualitative methods to analyze, assess, benchmark, and monitor AI risks and their impacts using appropriate metrics, tools, and techniques.', 'NIST AI RMF', '{"Govern","Map","Manage","TEVV","AI Risk Management Framework"}'::TEXT[], 'governance');
INSERT INTO sentinel_glossary (term, definition, source, related_terms, category) VALUES ('Manage', 'The fourth core function of the NIST AI RMF, focused on allocating resources and implementing plans to respond to, recover from, and communicate about AI risks based on the outputs of the Map and Measure functions.', 'NIST AI RMF', '{"Govern","Map","Measure","Risk treatment","AI Risk Management Framework"}'::TEXT[], 'governance');
